def clean_percent(value):
    if pd.isna(value):
        return 0
    if isinstance(value, str):
        value = value.replace("%", "").strip()
        try:
            value = float(value)
        except:
            return 0
    if value > 1:
        return value / 100
    return value


def _mlb_num(value, default=0.0):
    """Safely convert MLB Stats API numeric fields to float.

    The Stats API returns some values as strings, blanks, or placeholder dashes.
    Live model loaders use this for IP, SO, BB, ERA, batters faced, etc.
    """
    try:
        if value in [None, "", "-.---", "--"]:
            return default
        return float(str(value).replace("%", "").strip())
    except Exception:
        return default


def get_value(df, lookup_col, lookup_value, return_col, default=0):
    try:
        temp = df.copy()
        temp[lookup_col] = temp[lookup_col].astype(str).str.strip()
        lookup_value = str(lookup_value).strip()
        row = temp[temp[lookup_col] == lookup_value]

        if row.empty:
            return default

        value = row.iloc[0][return_col]

        if pd.isna(value):
            return default

        return value
    except:
        return default


def american_odds_to_implied_prob(odds):
    try:
        odds = float(odds)
        if odds < 0:
            return abs(odds) / (abs(odds) + 100)
        elif odds > 0:
            return 100 / (odds + 100)
        else:
            return 0
    except:
        return 0



def moneyline_grade(edge, confidence_score=None, confluence=None, risk_flags=None):
    """Grade moneylines using moving edge, confidence, confluence, and risk flags.

    V15.4 selection logic:
    - A Moneyline requires at least 10% moving edge.
    - B Moneyline requires at least 5% moving edge and remains subject to the same
      confidence, 3/4 confluence, and no-major-risk requirements.
    - Sportsbook odds remain part of implied probability and edge calculation, but
      no separate odds-range bucket can disqualify an otherwise qualified play.
    - Risky A setups become Non-Edge rather than being downgraded into B.
    """
    try:
        edge = float(edge or 0)
    except Exception:
        edge = 0.0

    # Quick-preview tables use the same thresholds as the full confidence layer.
    if confidence_score is None:
        if edge >= ML_A_EDGE_THRESHOLD:
            return "A Moneyline"
        if edge >= ML_B_EDGE_THRESHOLD:
            return "B Moneyline"
        return "Non-Edge Moneyline"

    try:
        confidence_score = float(confidence_score or 0)
    except Exception:
        confidence_score = 0.0
    try:
        confluence = int(confluence or 0)
    except Exception:
        confluence = 0

    risk_flags = [str(x) for x in (risk_flags or []) if str(x).strip()]
    has_major_risk = len(risk_flags) > 0

    if confluence < 3:
        return "Non-Edge Moneyline"

    # Tracker audit: extreme model edges need elite confirmation rather than being
    # promoted automatically by the size of the projection-market difference.
    if edge > ML_MONSTER_EDGE_THRESHOLD:
        if confluence >= 4 and confidence_score >= 82 and not has_major_risk:
            return "A Moneyline"
        return "Non-Edge Moneyline"

    if edge >= ML_A_EDGE_THRESHOLD:
        if confidence_score >= 75 and not has_major_risk:
            return "A Moneyline"
        return "Non-Edge Moneyline"

    if edge >= ML_B_EDGE_THRESHOLD:
        if confidence_score >= 65 and not has_major_risk:
            return "B Moneyline"
        return "Non-Edge Moneyline"

    return "Non-Edge Moneyline"


def extract_k_line(k_summary):
    text = str(k_summary)
    if "Line" not in text:
        return ""
    line_part = text.split("Line", 1)[1].strip()
    line_part = line_part.replace("/", "").strip()
    line_part = line_part.split("(", 1)[0].strip()
    return f"Line {line_part}" if line_part else ""


def to_last_first(name):
    """Convert MLB/API name format from 'First Last' to your Excel format 'Last, First'."""
    name = str(name).strip()
    if not name or name.lower() in ["nan", "none"]:
        return ""
    if name.upper() == "TBD":
        return "TBD"
    if "," in name:
        return name
    parts = name.split()
    if len(parts) <= 1:
        return name
    first = parts[0]
    last = " ".join(parts[1:])
    return f"{last}, {first}"


def to_first_last(name):
    """Convert your Excel name format 'Last, First' back to 'First Last' for odds prop matching."""
    name = str(name).strip()
    if not name or name.lower() in ["nan", "none"]:
        return ""
    if name.upper() == "TBD":
        return "TBD"
    if "," not in name:
        return name
    last, first = name.split(",", 1)
    return f"{first.strip()} {last.strip()}"


def normalize_name_for_match(name):
    return str(name).lower().replace(".", "").replace("'", "").strip()

