def _public_text_key(value):
    text = str(value or "").lower().replace("−", "-")
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


_PUBLIC_ALIAS_LOOKUP = {}
for _canonical_public_team, _aliases_public_team in _PUBLIC_MLB_TEAM_ALIASES.items():
    for _public_alias in [_canonical_public_team] + list(_aliases_public_team):
        _PUBLIC_ALIAS_LOOKUP[_public_text_key(_public_alias)] = _canonical_public_team


def normalize_public_team(value):
    key = _public_text_key(value)
    if not key:
        return ""
    if key in _PUBLIC_ALIAS_LOOKUP:
        return _PUBLIC_ALIAS_LOOKUP[key]
    # Prefer the longest contained alias so "White Sox" is not confused with "Red Sox".
    contained = [
        (len(alias_key), canonical)
        for alias_key, canonical in _PUBLIC_ALIAS_LOOKUP.items()
        if alias_key and (key.endswith(alias_key) or alias_key.endswith(key))
    ]
    if contained:
        return sorted(contained, reverse=True)[0][1]
    return str(value or "").strip()


def _public_now_text():
    try:
        if ZoneInfo is not None:
            return datetime.now(ZoneInfo("America/New_York")).strftime("%Y-%m-%d %I:%M %p ET")
    except Exception:
        pass
    return datetime.now().strftime("%Y-%m-%d %I:%M %p")


def _public_pct(value):
    try:
        return float(str(value or "").replace("%", "").strip())
    except Exception:
        return None


def _public_line_number(value):
    match = re.search(r"-?\d+(?:\.\d+)?", str(value or ""))
    try:
        return float(match.group(0)) if match else None
    except Exception:
        return None


def public_split_warning(public_bets, public_money):
    """Return prioritized public-market warning metadata.

    Crowded consensus is intentionally negative even when the handle agrees with
    the ticket count. This reflects the requested 80%/80% anti-crowding rule.
    """
    bets = _public_pct(public_bets)
    money = _public_pct(public_money)
    if bets is None or money is None:
        return {"code": "", "label": "", "negative": "", "gap": ""}

    money_minus_bets = money - bets
    bets_minus_money = bets - money
    if bets >= 90 and money >= 90:
        code, label, negative = "extreme_public_consensus", "Extreme Public Consensus", True
    elif bets >= 80 and money >= 80:
        code, label, negative = "heavy_public_consensus", "Heavy Public Consensus", True
    elif bets >= 80 and bets_minus_money >= 15:
        code, label, negative = "major_public_money_conflict", "Major Public/Money Conflict", True
    elif bets_minus_money >= 10:
        code, label, negative = "weak_money_support", "Weak Money Support", True
    elif bets < 50 and money_minus_bets >= 10:
        code, label, negative = "contrarian_money_support", "Contrarian Money Support", False
    elif bets < 80 and money_minus_bets >= 10:
        code, label, negative = "money_support", "Money Support", False
    else:
        code, label, negative = "balanced_public_split", "", False

    return {
        "code": code,
        "label": label,
        "negative": "TRUE" if negative else "FALSE",
        "gap": round(money_minus_bets, 1),
    }


def _public_html_tokens(raw_html):
    """Return visible HTML tokens with or without BeautifulSoup installed.

    The public Next.js route does not require BeautifulSoup, so the builder now has
    the same dependency-free fallback instead of marking DraftKings unavailable.
    """
    try:
        from bs4 import BeautifulSoup

        soup = BeautifulSoup(raw_html or "", "html.parser")
        for tag in soup(["script", "style", "noscript", "svg"]):
            tag.decompose()
        visible_text = soup.get_text("\n")
    except Exception:
        class _EmptyPublicSoup:
            @staticmethod
            def select(_selector):
                return []

        soup = _EmptyPublicSoup()
        visible_text = str(raw_html or "")
        visible_text = re.sub(r"<script\b[^>]*>[\s\S]*?</script>", " ", visible_text, flags=re.I)
        visible_text = re.sub(r"<style\b[^>]*>[\s\S]*?</style>", " ", visible_text, flags=re.I)
        visible_text = re.sub(r"<noscript\b[^>]*>[\s\S]*?</noscript>", " ", visible_text, flags=re.I)
        visible_text = re.sub(r"<svg\b[^>]*>[\s\S]*?</svg>", " ", visible_text, flags=re.I)
        visible_text = re.sub(r"<[^>]+>", "\n", visible_text)

    tokens = []
    for item in visible_text.splitlines():
        text = html.unescape(str(item)).replace("\xa0", " ").strip()
        text = re.sub(r"\s+", " ", text)
        if text:
            tokens.append(text)
    return tokens, soup


def _public_parse_event_date(value, year=None):
    match = re.search(r"(\d{1,2})/(\d{1,2})", str(value or ""))
    if not match:
        return ""
    year = int(year or MLB_SEASON)
    try:
        return date(year, int(match.group(1)), int(match.group(2))).isoformat()
    except Exception:
        return ""


def _public_is_odds(value):
    text = str(value or "").replace("−", "-").replace("+", "+").strip()
    return bool(re.fullmatch(r"[+-]?\d{3,4}", text))


def _public_is_percent(value):
    return bool(re.fullmatch(r"\d{1,3}(?:\.\d+)?%", str(value or "").strip()))


def parse_draftkings_betting_splits(raw_html, year=None):
    """Parse server-rendered DraftKings game cards into one record per selection."""
    tokens, _ = _public_html_tokens(raw_html)
    rows = []
    i = 0
    market_names = {"Moneyline": "Moneyline", "Run Line": "Run Line", "Spread": "Run Line", "Total": "Total"}

    while i < len(tokens) - 1:
        game_token = tokens[i]
        date_token = tokens[i + 1] if i + 1 < len(tokens) else ""
        if " @ " not in game_token or not re.search(r"\d{1,2}/\d{1,2}", date_token):
            i += 1
            continue

        away_raw, home_raw = [part.strip() for part in game_token.split(" @ ", 1)]
        away_team = normalize_public_team(away_raw)
        home_team = normalize_public_team(home_raw)
        # Ignore non-MLB events that may appear when DraftKings changes its default filter.
        if away_team not in _PUBLIC_MLB_TEAM_ALIASES or home_team not in _PUBLIC_MLB_TEAM_ALIASES:
            i += 2
            continue

        event_date = _public_parse_event_date(date_token, year=year)
        game_label = f"{away_team} at {home_team}"
        i += 2
        while i < len(tokens):
            if i + 1 < len(tokens) and " @ " in tokens[i] and re.search(r"\d{1,2}/\d{1,2}", tokens[i + 1]):
                break
            market = market_names.get(tokens[i])
            if not market:
                i += 1
                continue

            j = i + 1
            while j < len(tokens) and tokens[j] in {"Odds", "% Handle", "% Bets"}:
                j += 1

            parsed_market_rows = 0
            while j + 3 < len(tokens):
                if tokens[j] in market_names:
                    break
                if j + 1 < len(tokens) and " @ " in tokens[j] and re.search(r"\d{1,2}/\d{1,2}", tokens[j + 1]):
                    break
                selection, odds, money_pct, bets_pct = tokens[j:j + 4]
                if not (_public_is_odds(odds) and _public_is_percent(money_pct) and _public_is_percent(bets_pct)):
                    break

                warning = public_split_warning(bets_pct, money_pct)
                selection_line = _public_line_number(selection) if market in {"Run Line", "Total"} else ""
                rows.append({
                    "date": event_date,
                    "game": game_label,
                    "away_team": away_team,
                    "home_team": home_team,
                    "market": market,
                    "selection": selection,
                    "selection_team": normalize_public_team(re.sub(r"\s+[+-]?\d+(?:\.\d+)?$", "", selection)) if market != "Total" else "",
                    "side": "Over" if selection.lower().startswith("over") else "Under" if selection.lower().startswith("under") else "",
                    "line": selection_line,
                    "odds": odds.replace("−", "-"),
                    "public_money_pct": _public_pct(money_pct),
                    "public_bets_pct": _public_pct(bets_pct),
                    "public_gap_pct": warning.get("gap", ""),
                    "warning": warning.get("label", ""),
                    "warning_code": warning.get("code", ""),
                    "warning_negative": warning.get("negative", ""),
                    "source": PUBLIC_BETTING_SOURCE,
                    "source_url": DK_BETTING_SPLITS_URL,
                })
                parsed_market_rows += 1
                j += 4
                if parsed_market_rows >= 2:
                    break
            i = max(i + 1, j)
        # Outer loop resumes at the next game token.

    deduped = {}
    for row in rows:
        key = (row.get("date"), row.get("game"), row.get("market"), _public_text_key(row.get("selection")))
        deduped[key] = row
    return list(deduped.values())


def _public_prop_side_and_line(betslip_line):
    text = str(betslip_line or "").strip()
    if not text:
        return "", None
    lower = text.lower()
    if "under" in lower:
        return "Under", _public_line_number(text)
    if text.endswith("+"):
        threshold = _public_line_number(text)
        return "Over", (threshold - 0.5) if threshold is not None else None
    if "over" in lower:
        return "Over", _public_line_number(text)
    return "", _public_line_number(text)


def parse_draftkings_player_props(raw_html, year=None, rank_offset=0):
    """Parse the ordered Most Bet Player Props table; rank is by DraftKings handle."""
    tokens, soup = _public_html_tokens(raw_html)
    raw_rows = []

    # Prefer actual table rows when available.
    for tr in soup.select("tr"):
        cells = [re.sub(r"\s+", " ", cell.get_text(" ", strip=True)) for cell in tr.select("th,td")]
        if len(cells) >= 5 and " @ " in cells[0] and re.search(r"\d{1,2}/\d{1,2}", cells[1]):
            raw_rows.append(cells[:5])

    # Server-rendered fallback: locate groups of Event / Date / Market / Line / Odds.
    if not raw_rows:
        i = 0
        while i + 4 < len(tokens):
            if " @ " in tokens[i] and re.search(r"\d{1,2}/\d{1,2}", tokens[i + 1]) and _public_is_odds(tokens[i + 4]):
                raw_rows.append(tokens[i:i + 5])
                i += 5
            else:
                i += 1

    rows = []
    for row_index, (event, event_date_text, market, betslip_line, odds) in enumerate(raw_rows, start=1 + int(rank_offset or 0)):
        if " @ " not in event:
            continue
        away_raw, home_raw = [part.strip() for part in event.split(" @ ", 1)]
        away_team = normalize_public_team(away_raw)
        home_team = normalize_public_team(home_raw)
        if away_team not in _PUBLIC_MLB_TEAM_ALIASES or home_team not in _PUBLIC_MLB_TEAM_ALIASES:
            continue
        if "strikeout" not in market.lower():
            continue
        pitcher = re.sub(r"\s+Strikeouts?(?:\s+Thrown)?\s*$", "", market, flags=re.I).strip()
        side, comparable_line = _public_prop_side_and_line(betslip_line)
        rows.append({
            "date": _public_parse_event_date(event_date_text, year=year),
            "game": f"{away_team} at {home_team}",
            "away_team": away_team,
            "home_team": home_team,
            "pitcher": pitcher,
            "market": market,
            "betslip_line": betslip_line,
            "side": side,
            "line": comparable_line,
            "odds": str(odds).replace("−", "-"),
            "rank": row_index,
            "source": PUBLIC_BETTING_SOURCE,
            "source_url": DK_PLAYER_PROPS_URL,
        })
    return rows


def _public_fetch_html(url, params=None):
    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; EZPZ-Picks/1.0; +https://ezpzpicks.com)",
        "Accept": "text/html,application/xhtml+xml",
        "Accept-Language": "en-US,en;q=0.9",
    }
    response = requests.get(url, params=params or {}, headers=headers, timeout=8)
    response.raise_for_status()
    return response.text


@st.cache_data(ttl=300, show_spinner=False)
def load_draftkings_public_data():
    """Fetch and parse public splits/popularity with a five-minute Streamlit cache."""
    split_rows = []
    prop_rows = []
    errors = []

    for page in (1,):
        try:
            raw = _public_fetch_html(
                DK_BETTING_SPLITS_URL,
                {"itm_content": "MLB", "tb_edate": "n7days", "tb_eg": "MLB", "tb_page": page},
            )
            split_rows.extend(parse_draftkings_betting_splits(raw, year=MLB_SEASON))
        except Exception as exc:
            errors.append(f"splits page {page}: {exc}")
            if page == 1:
                # The unfiltered base page currently defaults to MLB and is a useful fallback.
                try:
                    split_rows.extend(parse_draftkings_betting_splits(_public_fetch_html(DK_BETTING_SPLITS_URL), year=MLB_SEASON))
                except Exception as fallback_exc:
                    errors.append(f"splits fallback: {fallback_exc}")

    rank_offset = 0
    for page in (1, 2):
        try:
            raw = _public_fetch_html(
                DK_PLAYER_PROPS_URL,
                {"itm_content": "MLB", "tb_edate": "n7days", "tb_eg": "MLB", "tb_page": page},
            )
            parsed = parse_draftkings_player_props(raw, year=MLB_SEASON, rank_offset=rank_offset)
            prop_rows.extend(parsed)
            rank_offset += max(25, len(parsed))
        except Exception as exc:
            errors.append(f"props page {page}: {exc}")
            if page == 1:
                try:
                    parsed = parse_draftkings_player_props(_public_fetch_html(DK_PLAYER_PROPS_URL), year=MLB_SEASON)
                    prop_rows.extend(parsed)
                    rank_offset += max(25, len(parsed))
                except Exception as fallback_exc:
                    errors.append(f"props fallback: {fallback_exc}")

    # Remove duplicate cards caused by alternate responsive markup or repeated pages.
    split_dedup = {}
    for row in split_rows:
        key = (row.get("date"), row.get("game"), row.get("market"), _public_text_key(row.get("selection")))
        split_dedup[key] = row
    prop_dedup = {}
    for row in prop_rows:
        key = (row.get("date"), row.get("game"), _public_text_key(row.get("pitcher")), row.get("betslip_line"))
        if key not in prop_dedup or int(row.get("rank", 9999)) < int(prop_dedup[key].get("rank", 9999)):
            prop_dedup[key] = row

    return {
        "splits": list(split_dedup.values()),
        "props": sorted(prop_dedup.values(), key=lambda x: int(x.get("rank", 9999))),
        "updated_at": _public_now_text(),
        "status": "LIVE" if split_dedup or prop_dedup else "UNAVAILABLE",
        "errors": " | ".join(errors),
    }


def _draftkings_today_et():
    try:
        if ZoneInfo is not None:
            return datetime.now(ZoneInfo("America/New_York")).date().isoformat()
    except Exception:
        pass
    return date.today().isoformat()


def _draftkings_split_key(row):
    return (
        str(row.get("date", "")),
        str(row.get("game", "")),
        str(row.get("market", "")),
        _public_text_key(row.get("selection", "")),
    )


def _draftkings_prop_key(row):
    return (
        str(row.get("date", "")),
        str(row.get("game", "")),
        _public_text_key(row.get("pitcher", "")),
        str(row.get("betslip_line", "")),
    )


def _merge_draftkings_public_data(current, previous=None):
    current = dict(current or {})
    previous = dict(previous or {})
    today = _draftkings_today_et()
    updated_at = current.get("updated_at", _public_now_text())

    split_map = {}
    for item in current.get("splits", []) or []:
        row = dict(item)
        row["retained"] = False
        row["last_seen_at"] = row.get("last_seen_at") or updated_at
        split_map[_draftkings_split_key(row)] = row
    prop_map = {}
    for item in current.get("props", []) or []:
        row = dict(item)
        row["retained"] = False
        row["last_seen_at"] = row.get("last_seen_at") or updated_at
        prop_map[_draftkings_prop_key(row)] = row

    for item in previous.get("splits", []) or []:
        row = dict(item)
        key = _draftkings_split_key(row)
        if str(row.get("date", "")) == today and key not in split_map:
            row["retained"] = True
            row["last_seen_at"] = row.get("last_seen_at") or previous.get("updated_at", updated_at)
            split_map[key] = row
    for item in previous.get("props", []) or []:
        row = dict(item)
        key = _draftkings_prop_key(row)
        if str(row.get("date", "")) == today and key not in prop_map:
            row["retained"] = True
            row["last_seen_at"] = row.get("last_seen_at") or previous.get("updated_at", updated_at)
            prop_map[key] = row

    current["splits"] = list(split_map.values())
    current["props"] = sorted(prop_map.values(), key=lambda row: int(row.get("rank", 9999) or 9999))
    current["retained_count"] = sum(1 for row in current["splits"] + current["props"] if row.get("retained"))
    return current


def get_draftkings_public_data(force_refresh=False):
    if force_refresh:
        try:
            load_draftkings_public_data.clear()
        except Exception:
            pass

    current = load_draftkings_public_data()
    previous = st.session_state.get("draftkings_last_loaded_data", {})
    merged = _merge_draftkings_public_data(current, previous)

    if merged.get("status") != "UNAVAILABLE" or merged.get("splits") or merged.get("props"):
        st.session_state["draftkings_last_loaded_data"] = merged
    elif previous:
        merged = _merge_draftkings_public_data(previous, previous)
        merged["status"] = "LAST LOADED"
        merged["errors"] = " | ".join(
            value for value in [previous.get("errors", ""), current.get("errors", "")] if str(value).strip()
        )
    return merged


def _public_same_game(row, away_team, home_team, slate_date):
    return (
        str(row.get("date", "")) == str(slate_date)
        and normalize_public_team(row.get("away_team", "")) == normalize_public_team(away_team)
        and normalize_public_team(row.get("home_team", "")) == normalize_public_team(home_team)
    )


def match_public_game_split(rows, away_team, home_team, slate_date, market, selection, line=None):
    candidates = [
        row for row in (rows or [])
        if _public_same_game(row, away_team, home_team, slate_date)
        and str(row.get("market", "")).lower() == str(market).lower()
    ]
    if not candidates:
        return {}

    selected_team = normalize_public_team(selection)
    selected_side = str(selection or "").strip().lower()
    if market == "Moneyline":
        candidates = [row for row in candidates if normalize_public_team(row.get("selection_team", row.get("selection", ""))) == selected_team]
    elif market == "Total":
        side = "over" if "over" in selected_side else "under" if "under" in selected_side else selected_side
        candidates = [row for row in candidates if str(row.get("side", "")).lower() == side]
    elif market == "Run Line":
        candidates = [row for row in candidates if normalize_public_team(row.get("selection_team", "")) == selected_team]
    if not candidates:
        return {}

    target_line = _public_line_number(line)
    if target_line is not None and market in {"Total", "Run Line"}:
        exact = [row for row in candidates if row.get("line") is not None and abs(float(row.get("line")) - target_line) < 0.01]
        if exact:
            matched = exact[0].copy()
            matched["match_confidence"] = "Exact market/side/line"
            return matched
        matched = min(candidates, key=lambda row: abs(float(row.get("line", target_line) or target_line) - target_line)).copy()
        matched["match_confidence"] = "Market/side matched; line differs"
        return matched

    matched = candidates[0].copy()
    matched["match_confidence"] = "Exact market/selection"
    return matched


def match_public_pitcher_prop(rows, away_team, home_team, slate_date, pitcher, side, line):
    pitcher_key = _public_text_key(to_first_last(pitcher))
    candidates = [
        row for row in (rows or [])
        if _public_same_game(row, away_team, home_team, slate_date)
        and _public_text_key(row.get("pitcher", "")) == pitcher_key
    ]
    if not candidates:
        return {}

    target_side = "Over" if "OVER" in str(side or "").upper() else "Under" if "UNDER" in str(side or "").upper() else ""
    target_line = _public_line_number(line)
    exact = [
        row for row in candidates
        if (not target_side or str(row.get("side", "")) == target_side)
        and (target_line is None or row.get("line") is None or abs(float(row.get("line")) - target_line) < 0.01)
    ]
    if exact:
        matched = sorted(exact, key=lambda row: int(row.get("rank", 9999)))[0].copy()
        matched["match_confidence"] = "Exact pitcher/side/line"
        matched["popularity_flag"] = "TRUE"
        return matched

    matched = sorted(candidates, key=lambda row: int(row.get("rank", 9999)))[0].copy()
    matched["match_confidence"] = "Pitcher listed; side or line differs"
    matched["popularity_flag"] = "FALSE"
    return matched


def collect_public_betting_context(
    away_team, home_team, slate_date, better_ml_team, total_grade, total_line,
    away_pitcher="", away_k_grade="", away_k_line="",
    home_pitcher="", home_k_grade="", home_k_line="",
    away_bulk_pitcher="", away_bulk_grade="", away_bulk_line="",
    home_bulk_pitcher="", home_bulk_grade="", home_bulk_line="",
):
    try:
        data = get_draftkings_public_data()
    except Exception as exc:
        return {"status": "UNAVAILABLE", "updated_at": _public_now_text(), "error": str(exc)}

    split_rows = data.get("splits", [])
    prop_rows = data.get("props", [])
    total_side = "Over" if "OVER" in str(total_grade or "").upper() else "Under" if "UNDER" in str(total_grade or "").upper() else ""
    context = {
        "status": data.get("status", "UNAVAILABLE"),
        "updated_at": data.get("updated_at", _public_now_text()),
        "error": data.get("errors", ""),
        "split_count": len(split_rows),
        "prop_count": len(prop_rows),
        "retained_count": int(data.get("retained_count", 0) or 0),
        "ml": match_public_game_split(split_rows, away_team, home_team, slate_date, "Moneyline", better_ml_team),
        "total": match_public_game_split(split_rows, away_team, home_team, slate_date, "Total", total_side, total_line) if total_side else {},
        "run_line": match_public_game_split(split_rows, away_team, home_team, slate_date, "Run Line", better_ml_team),
        "away_prop": match_public_pitcher_prop(prop_rows, away_team, home_team, slate_date, away_pitcher, away_k_grade, away_k_line) if away_pitcher else {},
        "home_prop": match_public_pitcher_prop(prop_rows, away_team, home_team, slate_date, home_pitcher, home_k_grade, home_k_line) if home_pitcher else {},
        "away_bulk_prop": match_public_pitcher_prop(prop_rows, away_team, home_team, slate_date, away_bulk_pitcher, away_bulk_grade, away_bulk_line) if away_bulk_pitcher else {},
        "home_bulk_prop": match_public_pitcher_prop(prop_rows, away_team, home_team, slate_date, home_bulk_pitcher, home_bulk_grade, home_bulk_line) if home_bulk_pitcher else {},
    }
    return context


def load_public_split_snapshots():
    return read_sheet(PUBLIC_SPLIT_TAB, PUBLIC_SPLIT_COLUMNS)


def save_public_split_snapshots(df):
    return write_sheet(PUBLIC_SPLIT_TAB, df, PUBLIC_SPLIT_COLUMNS)


def append_public_split_snapshots(context, away_team, home_team, slate_date):
    if not context:
        return 0
    snapshot_time = context.get("updated_at", _public_now_text())
    records = []
    for key in ["ml", "total", "run_line"]:
        item = context.get(key) or {}
        if not item:
            continue
        records.append({
            "Snapshot Time ET": snapshot_time,
            "Date": str(slate_date),
            "Game": f"{away_team} at {home_team}",
            "Away Team": away_team,
            "Home Team": home_team,
            "Data Type": "Game Market",
            "Market": item.get("market", ""),
            "Selection": item.get("selection", ""),
            "Line": item.get("line", ""),
            "Odds": item.get("odds", ""),
            "Public Bets %": item.get("public_bets_pct", ""),
            "Public Money %": item.get("public_money_pct", ""),
            "Public Gap %": item.get("public_gap_pct", ""),
            "Warning": item.get("warning", ""),
            "Warning Negative": item.get("warning_negative", ""),
            "Popularity Rank": "",
            "Source": item.get("source", PUBLIC_BETTING_SOURCE),
            "Match Confidence": item.get("match_confidence", ""),
            "Source URL": item.get("source_url", DK_BETTING_SPLITS_URL),
        })
    for key in ["away_prop", "home_prop", "away_bulk_prop", "home_bulk_prop"]:
        item = context.get(key) or {}
        if not item:
            continue
        records.append({
            "Snapshot Time ET": snapshot_time,
            "Date": str(slate_date),
            "Game": f"{away_team} at {home_team}",
            "Away Team": away_team,
            "Home Team": home_team,
            "Data Type": "Player Prop Popularity",
            "Market": item.get("market", ""),
            "Selection": item.get("pitcher", ""),
            "Line": item.get("betslip_line", item.get("line", "")),
            "Odds": item.get("odds", ""),
            "Public Bets %": "",
            "Public Money %": "",
            "Public Gap %": "",
            "Warning": "Popular Player Prop" if item.get("popularity_flag") == "TRUE" else "",
            "Warning Negative": "",
            "Popularity Rank": item.get("rank", ""),
            "Source": item.get("source", PUBLIC_BETTING_SOURCE),
            "Match Confidence": item.get("match_confidence", ""),
            "Source URL": item.get("source_url", DK_PLAYER_PROPS_URL),
        })
    if not records:
        return 0

    df = load_public_split_snapshots()
    out = pd.concat([df, pd.DataFrame(records)], ignore_index=True)
    dedupe_cols = ["Snapshot Time ET", "Date", "Game", "Data Type", "Market", "Selection", "Line"]
    out = out.drop_duplicates(subset=[col for col in dedupe_cols if col in out.columns], keep="last")
    save_public_split_snapshots(out)
    return len(records)


