def save_all_game_trends(df):
    return write_sheet(ALL_GAME_TRENDS_TAB, df, ALL_GAME_TRENDS_COLUMNS)


def upsert_all_game_trend_rows(rows):
    """Upsert all-side research rows without disturbing locked results or snapshots."""
    if not rows:
        return True

    df = load_all_game_trends()
    if df is None or df.empty:
        df = pd.DataFrame(columns=ALL_GAME_TRENDS_COLUMNS)
    else:
        df = df.copy()

    for col in ALL_GAME_TRENDS_COLUMNS:
        if col not in df.columns:
            df[col] = ""
    df = df[ALL_GAME_TRENDS_COLUMNS].astype(object)

    for incoming in rows:
        new_row = {col: incoming.get(col, "") for col in ALL_GAME_TRENDS_COLUMNS}
        date_key = str(new_row.get("Date", "")).strip()
        game_key = str(new_row.get("Game Key", "")).strip()
        market_key = str(new_row.get("Market", "")).strip().upper()

        side_key = str(new_row.get("Side", "")).strip().upper()
        selection_key = str(new_row.get("Selection", "")).strip().lower()
        if game_key:
            mask = (
                df["Date"].astype(str).str.strip().eq(date_key)
                & df["Game Key"].astype(str).str.strip().eq(game_key)
                & df["Market"].astype(str).str.strip().str.upper().eq(market_key)
            )
        else:
            mask = (
                df["Date"].astype(str).str.strip().eq(date_key)
                & df["Game"].astype(str).str.strip().eq(str(new_row.get("Game", "")).strip())
                & df["Market"].astype(str).str.strip().str.upper().eq(market_key)
            )

        # The research table now stores both moneyline teams and both total sides.
        # Include the selected team/direction in the upsert key so those four rows
        # coexist without changing any model selection or qualification behavior.
        if market_key == "TOTAL" and side_key:
            mask = mask & df["Side"].astype(str).str.strip().str.upper().eq(side_key)
        else:
            mask = mask & df["Selection"].astype(str).str.strip().str.lower().eq(selection_key)

        matches = df.index[mask].tolist()
        if matches:
            idx = matches[-1]
            existing = df.loc[idx].to_dict()
            for col in _ALL_GAME_TRENDS_PERSISTENT_COLUMNS:
                if str(existing.get(col, "")).strip():
                    new_row[col] = existing.get(col, "")
            for col in ALL_GAME_TRENDS_COLUMNS:
                df.at[idx, col] = new_row.get(col, "")
            # Remove accidental duplicates while keeping the most recent row position.
            if len(matches) > 1:
                df = df.drop(index=matches[:-1])
        else:
            df = pd.concat([df, pd.DataFrame([new_row])], ignore_index=True)

    return save_all_game_trends(df.reset_index(drop=True))


def pct_to_float(value):
    try:
        text = str(value).replace("%", "").strip()
        if text == "" or text.lower() == "nan":
            return 0.0
        return float(text)
    except Exception:
        return 0.0


def parse_american_odds(value):
    """Pull American odds out of Odds/Line.
    Works for values like -110, +125, "4.5 / -110", or "Line 4.5 Odds -110".
    """
    import re
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    text = str(value).strip()
    if not text:
        return None
    matches = re.findall(r"[+-]?\d+", text)
    if not matches:
        return None
    try:
        odds = int(matches[-1])
    except Exception:
        return None
    if -99 < odds < 100:
        return None
    return odds


def profit_units_from_american_odds(odds, result):
    """Assumes 1 unit risked per tracked bet."""
    if result == "Push":
        return 0.0
    if result == "Loss":
        return -1.0
    if result != "Win":
        return 0.0
    odds = parse_american_odds(odds)
    if odds is None:
        odds = -110
    if odds > 0:
        return odds / 100
    return 100 / abs(odds)


def sort_tracker_by_model_pct(df):
    if df is None or df.empty or "Model %" not in df.columns:
        return df
    out = df.copy()
    out["_model_pct_sort"] = out["Model %"].apply(pct_to_float)
    out = out.sort_values("_model_pct_sort", ascending=False).drop(columns=["_model_pct_sort"])
    return out


def styled_tracker_dataframe(df):
    if df is None or df.empty:
        return df

    def row_style(row):
        pct = pct_to_float(row.get("Model %", 0))

        if pct >= 65:
            style = "background-color: #d1fae5; color: #065f46; font-weight: bold;"
        elif pct >= 58:
            style = "background-color: #fef3c7; color: #92400e; font-weight: bold;"
        elif pct > 50:
            style = "background-color: #e0f2fe; color: #075985; font-weight: bold;"
        else:
            style = ""

        return [style] * len(row)

    return df.style.apply(row_style, axis=1)


def display_tracker_dataframe(df):
    if df is None or df.empty:
        st.dataframe(df, use_container_width=True, hide_index=True)
        return
    df = sort_tracker_by_model_pct(df)
    column_config = {col: st.column_config.TextColumn(col, width="small") for col in df.columns}
    for col in ["Selection", "Market", "Bet Type"]:
        if col in column_config:
            column_config[col] = st.column_config.TextColumn(col, width="medium")
    st.dataframe(styled_tracker_dataframe(df), use_container_width=True, hide_index=True, column_config=column_config)


