def add_slate_row(
    away_team,
    home_team,
    better_ml,
    ml_odds,
    ml_grade,
    nrfi_grade,
    away_pitcher_k_grade,
    away_pitcher_k_score,
    home_pitcher_k_grade,
    home_pitcher_k_score,
    total_runs_projection_value="",
    total_runs_grade="",
    total_runs_line="",
    total_runs_odds="",
    game_id="",
    game_label="",
    game_time="",
    slate_date=None,
    nrfi_score_value="",
    nrfi_probability_value="",
    nrfi_odds_value="",
    away_k_reliability="", away_k_probability="", home_k_reliability="", home_k_probability="",
    away_most_likely_k="", home_most_likely_k="",
    away_bulk_summary="", away_bulk_score="", away_bulk_reliability="",
    away_bulk_most_likely_k="",
    home_bulk_summary="", home_bulk_score="", home_bulk_reliability="",
    home_bulk_most_likely_k="",
    total_selected_probability="", total_reliability="",
    correlation_block=False, correlation_reason="", correlation_play_count="",
    public_context=None
):
    df = load_slate()
    save_date = str(slate_date or today_et_string())
    game_id_text = str(game_id).strip()

    first_inning_grade = str(nrfi_grade or "").strip().upper()
    is_yrfi_play = "YRFI" in first_inning_grade

    # Save NRFI and YRFI metrics in separate columns. The public site interprets
    # a value under "NRFI Score" as an NRFI-side score and flips it for YRFI.
    # Keeping the selected YRFI score in a dedicated column prevents a second
    # inversion and ensures the public tile receives the correct EZPZ score.
    public_context = public_context or {}
    public_updated = public_context.get("updated_at", "")
    new_row = {
        "Date": save_date,
        "Game Key": game_id_text,
        "Game Label": game_label or f"{away_team} at {home_team}",
        "Game Time": str(game_time or ""),
        "Away Team": away_team,
        "Home Team": home_team,
        "Better ML": better_ml,
        "ML Odds": ml_odds,
        "ML Grade": ml_grade,
        "NRFI Grade": nrfi_grade,
        "NRFI Score": "" if is_yrfi_play else nrfi_score_value,
        "NRFI Probability": "" if is_yrfi_play else nrfi_probability_value,
        "NRFI Odds": "" if is_yrfi_play else nrfi_odds_value,
        "YRFI Score": nrfi_score_value if is_yrfi_play else "",
        "YRFI Probability": nrfi_probability_value if is_yrfi_play else "",
        "YRFI Odds": nrfi_odds_value if is_yrfi_play else "",
        "Away Pitcher K + Grade": away_pitcher_k_grade,
        "Away Pitcher K Score": away_pitcher_k_score,
        "Away Pitcher Most Likely K": away_most_likely_k,
        "Home Pitcher K + Grade": home_pitcher_k_grade,
        "Home Pitcher K Score": home_pitcher_k_score,
        "Home Pitcher Most Likely K": home_most_likely_k,
        "Total Runs Projection": total_runs_projection_value,
        "Total Runs Grade": total_runs_grade,
        "Total Runs Line": total_runs_line,
        "Total Runs Odds": total_runs_odds,
        "Away Pitcher K Reliability": away_k_reliability,
        "Away Pitcher K Probability": away_k_probability,
        "Home Pitcher K Reliability": home_k_reliability,
        "Home Pitcher K Probability": home_k_probability,
        "Away Bulk Pitcher K + Grade": away_bulk_summary,
        "Away Bulk Pitcher K Score": away_bulk_score,
        "Away Bulk Pitcher K Reliability": away_bulk_reliability,
        "Away Bulk Pitcher Most Likely K": away_bulk_most_likely_k,
        "Home Bulk Pitcher K + Grade": home_bulk_summary,
        "Home Bulk Pitcher K Score": home_bulk_score,
        "Home Bulk Pitcher K Reliability": home_bulk_reliability,
        "Home Bulk Pitcher Most Likely K": home_bulk_most_likely_k,
        "Total Selected Probability": total_selected_probability,
        "Total Reliability": total_reliability,
        "Model Version": MODEL_VERSION,
        "Correlation Block": "TRUE" if bool(correlation_block) else "FALSE",
        "Correlation Reason": str(correlation_reason or ""),
        "Correlation Play Count": correlation_play_count,
        "Public Data Status": public_context.get("status", "UNAVAILABLE"),
        "Public Data Updated": public_updated,
        "Public Data Error": public_context.get("error", ""),
        **_slate_split_fields("ML", public_context.get("ml")),
        **_slate_split_fields("Total", public_context.get("total")),
        **_slate_split_fields("Run Line", public_context.get("run_line")),
        **_slate_prop_fields("Away Pitcher", public_context.get("away_prop"), public_updated),
        **_slate_prop_fields("Home Pitcher", public_context.get("home_prop"), public_updated),
        **_slate_prop_fields("Away Bulk", public_context.get("away_bulk_prop"), public_updated),
        **_slate_prop_fields("Home Bulk", public_context.get("home_bulk_prop"), public_updated),
    }

    # Replace an earlier save of the same game/date rather than leaving stale
    # unblocked duplicates that could still leak into Best Plays.
    if df is not None and not df.empty:
        date_mask = df["Date"].astype(str).str.strip() == save_date
        if game_id_text and "Game Key" in df.columns:
            game_mask = df["Game Key"].astype(str).str.strip() == game_id_text
        else:
            saved_label = str(new_row.get("Game Label", "")).strip()
            game_mask = df["Game Label"].astype(str).str.strip() == saved_label
        df = df.loc[~(date_mask & game_mask)].copy()

    df = pd.concat([df, pd.DataFrame([new_row])], ignore_index=True)
    save_slate(df)


def _truthy_flag(value):
    """Interpret Google Sheets booleans and common text flags safely."""
    if isinstance(value, bool):
        return value
    text = str(value or "").strip().upper()
    return text in {"TRUE", "1", "YES", "Y", "BLOCKED"}


def slate_row_correlation_blocked(row):
    """Return True when the whole saved game is shadow-only due to correlation."""
    if _truthy_flag(row.get("Correlation Block", "")):
        return True
    # Backward compatibility for any row where only the reason was saved.
    reason = str(row.get("Correlation Reason", "") or "").strip().upper()
    return bool(reason and "CORRELATION" in reason and "BLOCK" in reason)


def remove_pending_tracker_rows_for_game(game_key, slate_date=None):
    """Remove previously published pending bets when a game becomes correlation-blocked.

    Completed historical rows are preserved. The saved Daily Slate row retains every
    original projection/grade as the shadow record for the blocked game.
    """
    game_key_text = str(game_key or "").strip()
    if not game_key_text:
        return 0

    tracker = load_tracker()
    if tracker is None or tracker.empty or "Game Key" not in tracker.columns:
        return 0

    day = str(slate_date or today_et_string())
    game_mask = tracker["Game Key"].astype(str).str.strip() == game_key_text
    date_mask = tracker["Date"].astype(str).str.strip() == day if "Date" in tracker.columns else True
    result_text = tracker["Result"].astype(str).str.strip().str.upper() if "Result" in tracker.columns else pd.Series("", index=tracker.index)
    pending_mask = result_text.isin(["", "PENDING"])
    remove_mask = game_mask & date_mask & pending_mask
    removed = int(remove_mask.sum())
    if removed:
        tracker = tracker.loc[~remove_mask].copy()
        save_tracker(tracker)
    return removed


