@st.cache_data(ttl=900, show_spinner=False)
def _game_results_for_date(game_date):
    """Load all final MLB results for a date in one request when possible."""
    results = {}
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/schedule",
            params={"sportId": 1, "date": str(game_date), "hydrate": "linescore"},
            timeout=25,
        )
        response.raise_for_status()
        data = response.json()
        for day in data.get("dates", []) or []:
            for game in day.get("games", []) or []:
                status_data = game.get("status", {}) or {}
                state = str(status_data.get("detailedState", status_data.get("abstractGameState", "")) or "")
                if "final" not in state.lower():
                    continue
                game_key = _normalize_game_key(game.get("gamePk", ""))
                if not game_key:
                    continue
                linescore = game.get("linescore", {}) or {}
                teams = game.get("teams", {}) or {}
                away_runs = int(((teams.get("away") or {}).get("score", 0)) or 0)
                home_runs = int(((teams.get("home") or {}).get("score", 0)) or 0)
                innings = linescore.get("innings", []) or []
                first = innings[0] if innings else {}
                first_runs = int(((first.get("away") or {}).get("runs", 0)) or 0) + int(((first.get("home") or {}).get("runs", 0)) or 0)
                results[game_key] = {
                    "away_runs": away_runs,
                    "home_runs": home_runs,
                    "first_inning_runs": first_runs,
                }
    except Exception:
        return {}
    return results

def _k15_canonical_team_label(value):
    """Return the model's canonical MLB team label for names, abbreviations, or aliases."""
    raw = str(value or "").strip()
    if not raw or raw.lower() in ["nan", "none", "<na>"]:
        return ""
    raw_key = normalize_name_for_match(raw)
    for canonical, aliases in TEAM_NAME_ALIASES_FOR_SAVANT.items():
        alias_keys = {
            normalize_name_for_match(x)
            for x in ([canonical] + list(aliases))
            if str(x).strip()
        }
        if raw_key in alias_keys:
            return canonical
    return raw

@st.cache_data(ttl=6 * 60 * 60, show_spinner=False)
def _k15_mlb_player_team_lookup(year=MLB_SEASON):
    """Build MLBAM-ID/name-to-current-team mappings for Savant rows without a team column.

    Savant's custom player CSV does not consistently expose a team field. This
    combines the official active-roster directory with season hitting splits,
    preferring the active roster and using the largest season PA split only as a
    fallback for injured, optioned, or recently moved players.
    """
    directory = _k15_mlb_team_directory(year)
    id_lookup = {}
    name_lookup = {}

    # First preference: current official rosters, fetched in one hydrated request.
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/teams",
            params={"sportId": 1, "season": int(year), "hydrate": "roster"},
            timeout=40,
        )
        response.raise_for_status()
        for team in response.json().get("teams", []):
            canonical = _k15_team_from_id_or_value(team.get("name", ""), team.get("id", ""), directory)
            roster_container = team.get("roster", {}) or {}
            roster = roster_container.get("roster", []) if isinstance(roster_container, dict) else roster_container
            for entry in roster or []:
                person = entry.get("person", {}) or {}
                player_id = str(person.get("id", "") or "").strip()
                full_name = str(person.get("fullName", "") or "").strip()
                if player_id and canonical:
                    id_lookup[player_id] = canonical
                if full_name and canonical:
                    name_lookup[normalize_name_for_match(full_name)] = canonical
                    name_lookup[normalize_name_for_match(to_last_first(full_name))] = canonical
    except Exception:
        pass

    # Second preference: season hitting splits. Keep the largest-PA team split.
    weighted_candidates = {}
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/stats",
            params={
                "stats": "season", "group": "hitting", "playerPool": "ALL",
                "season": int(year), "sportIds": 1, "limit": 5000,
            },
            timeout=45,
        )
        response.raise_for_status()
        for block in response.json().get("stats", []):
            for split in block.get("splits", []):
                player = split.get("player", {}) or {}
                team = split.get("team", {}) or {}
                stat = split.get("stat", {}) or {}
                player_id = str(player.get("id", "") or "").strip()
                full_name = str(player.get("fullName", "") or "").strip()
                canonical = _k15_team_from_id_or_value(team.get("name", ""), team.get("id", ""), directory)
                pa = _k15_float(stat.get("plateAppearances", 0), 0.0)
                if pa <= 0:
                    pa = sum(_k15_float(stat.get(k, 0), 0.0) for k in ["atBats", "baseOnBalls", "hitByPitch", "sacFlies"])
                candidate_key = player_id or normalize_name_for_match(full_name)
                if candidate_key and canonical:
                    current = weighted_candidates.get(candidate_key)
                    if current is None or pa > current[0]:
                        weighted_candidates[candidate_key] = (pa, canonical, full_name, player_id)
    except Exception:
        pass

    for _, canonical, full_name, player_id in weighted_candidates.values():
        if player_id and player_id not in id_lookup:
            id_lookup[player_id] = canonical
        if full_name:
            for key in [normalize_name_for_match(full_name), normalize_name_for_match(to_last_first(full_name))]:
                if key and key not in name_lookup:
                    name_lookup[key] = canonical

    return {"by_id": id_lookup, "by_name": name_lookup, "source": "Official MLB rosters + season hitting splits"}

@st.cache_data(ttl=6 * 60 * 60, show_spinner=False)
def _k15_mlb_team_directory(year=MLB_SEASON):
    """Official MLB team ID/name directory used to resolve Savant team identifiers."""
    rows = []
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/teams",
            params={"sportId": 1, "season": int(year)},
            timeout=30,
        )
        response.raise_for_status()
        for team in response.json().get("teams", []):
            team_id = str(team.get("id", "") or "").strip()
            aliases = [
                team.get("name", ""), team.get("teamName", ""), team.get("clubName", ""),
                team.get("shortName", ""), team.get("abbreviation", ""),
                team.get("locationName", ""), team.get("franchiseName", ""),
            ]
            canonical = _k15_canonical_team_label(team.get("name", ""))
            if not canonical:
                canonical = _normalize_mlb_team_name(team.get("name", ""))
            rows.append({
                "team_id": team_id,
                "canonical": canonical,
                "aliases": [str(x).strip() for x in aliases if str(x or "").strip()],
            })
    except Exception:
        rows = []
    return rows

@st.cache_data(ttl=60 * 60, show_spinner=False)
def _k15_official_team_discipline_rows(year=MLB_SEASON):
    """Partial official MLB fallback for K%, BB%, and pitches per PA by team."""
    rows = []
    try:
        response = requests.get(
            "https://statsapi.mlb.com/api/v1/teams/stats",
            params={"sportIds": 1, "group": "hitting", "stats": "season", "season": int(year)},
            timeout=35,
        )
        response.raise_for_status()
        for block in response.json().get("stats", []):
            for split in block.get("splits", []):
                team = split.get("team", {}) or {}
                stat = split.get("stat", {}) or {}
                pa = _k15_float(stat.get("plateAppearances", 0), 0.0)
                if pa <= 0:
                    pa = sum(_k15_float(stat.get(k, 0), 0.0) for k in ["atBats", "baseOnBalls", "hitByPitch", "sacFlies"])
                strikeouts = _k15_float(stat.get("strikeOuts", 0), 0.0)
                walks = _k15_float(stat.get("baseOnBalls", 0), 0.0)
                pitches = _k15_float(stat.get("numberOfPitches", stat.get("pitches", 0)), 0.0)
                rows.append({
                    "Team": _k15_canonical_team_label(team.get("name", "")),
                    "PA": pa,
                    "K %": strikeouts / pa if pa > 0 else 0.0,
                    "BB %": walks / pa if pa > 0 else 0.0,
                    "Pitches/PA": pitches / pa if pa > 0 and pitches > 0 else 0.0,
                })
    except Exception:
        return pd.DataFrame()
    return pd.DataFrame(rows)

def _k15_partial_team_discipline_fallback(team, baseline, year=MLB_SEASON, reason=""):
    """Use official team K/BB/pitch-count data when full Savant team aggregation is unavailable."""
    try:
        table = _k15_official_team_discipline_rows(year)
    except Exception:
        table = pd.DataFrame()
    target_keys = _team_keys(team)
    if table is not None and not table.empty:
        matches = table[table["Team"].apply(lambda value: bool(_team_keys(value).intersection(target_keys)))]
        if not matches.empty:
            row = matches.iloc[0]
            out = dict(baseline)
            for output, column in [("pa", "PA"), ("k_pct", "K %"), ("bb_pct", "BB %"), ("pitches_per_pa", "Pitches/PA")]:
                value = _k15_float(row.get(column, 0), 0.0)
                if value > 0:
                    out[output] = value
            out.update({
                "source": "Official MLB Stats API partial team discipline fallback",
                "availability": "partial",
                "available": False,
                "resolved_team": str(row.get("Team", team)),
                "fallback_reason": reason or "Full Savant team plate-discipline aggregation unavailable",
                "team_mapping_source": "Official MLB team aggregate",
            })
            return out
    out = dict(baseline)
    out.update({
        "source": "League-neutral fallback",
        "availability": "unavailable",
        "available": False,
        "resolved_team": _k15_canonical_team_label(team),
        "fallback_reason": reason or "Savant and official MLB team-discipline fallbacks unavailable",
        "team_mapping_source": "None",
    })
    return out

def _k15_robust_center(values):
    """Return a trimmed median to reduce Statcast tracking outlier influence."""
    series = pd.to_numeric(values, errors="coerce").dropna()
    if series.empty:
        return None
    if len(series) >= 12:
        low = series.quantile(0.05)
        high = series.quantile(0.95)
        trimmed = series[(series >= low) & (series <= high)]
        if not trimmed.empty:
            series = trimmed
    value = series.median()
    return float(value) if pd.notna(value) else None

def _k15_team_from_id_or_value(value="", team_id="", directory=None):
    """Resolve a direct Savant team value or numeric team ID to a canonical label."""
    directory = directory if directory is not None else _k15_mlb_team_directory(MLB_SEASON)
    id_text = str(team_id or "").replace(".0", "").strip()
    raw = str(value or "").strip()
    if not id_text and raw.replace(".0", "").isdigit():
        id_text = raw.replace(".0", "")
    if id_text:
        for item in directory or []:
            if str(item.get("team_id", "")) == id_text:
                return str(item.get("canonical", "") or "")
    direct = _k15_canonical_team_label(raw)
    if direct and direct != raw:
        return direct
    raw_key = normalize_name_for_match(raw)
    if raw_key:
        for item in directory or []:
            alias_keys = {
                normalize_name_for_match(x)
                for x in [item.get("canonical", "")] + list(item.get("aliases", []))
                if str(x).strip()
            }
            if raw_key in alias_keys:
                return str(item.get("canonical", "") or raw)
    return direct

def _matchup_details_date_text(details_date=None):
    """Return a YYYY-MM-DD slate date, defaulting to the current Eastern date.

    Render commonly runs on UTC. Using date.today() here made the temporary
    matchup-details tab roll to tomorrow at 8:00 PM ET during daylight saving
    time, which deleted the current day's saved matchups too early.
    """
    if details_date not in [None, ""]:
        try:
            return details_date.strftime("%Y-%m-%d")
        except Exception:
            return str(details_date)[:10]
    return today_et_string()

def _normalize_game_key(value):
    text = str(value or "").strip()
    if text.endswith(".0") and text[:-2].isdigit():
        text = text[:-2]
    return text

def _v15_5_bool_text(value):
    return "TRUE" if bool(value) else "FALSE"

def _v15_5_apply_k_publication_rules(grade, role="Starter", lineup_details=None, arsenal_details=None, volatility="", game_environment=None):
    """Publish qualified starter Unders while keeping opener/bulk Unders shadow-only."""
    original = str(grade or "PASS").upper().strip()
    published = original
    reasons = []
    role_upper = str(role or "Starter").upper().strip()
    hitters = int((lineup_details or {}).get("hitters_found", 0) or 0)
    # A confirmed nine-man batting order no longer requires nine separate player
    # stat profiles. Missing/rookie profiles are handled upstream with the team
    # baseline, so profile coverage is diagnostic rather than a publication gate.
    lineup_count = len((lineup_details or {}).get("hitters", [])) if (lineup_details or {}).get("hitters") is not None else 0
    nine_hitter_passed = lineup_count >= 9 or hitters >= 9

    workload = (arsenal_details or {}).get("workload", {}) or {}
    projected_pitches = _k15_float(workload.get("projected_pitches"), 0.0)
    projected_bf = _k15_float(workload.get("projected_bf"), 0.0)
    projected_ip = _k15_float(workload.get("projected_start_ip"), 0.0)
    if projected_pitches <= 0 and projected_ip > 0:
        projected_pitches = _pitch_count_projection(projected_ip, role_upper.title())
    if projected_bf <= 0 and projected_ip > 0:
        projected_bf = _projected_batters_faced(projected_ip)

    workload_supported = projected_pitches >= 88.0 and projected_bf >= 22.0
    partial_workload_support = projected_pitches >= 88.0 or projected_bf >= 22.0

    env_hook = str((game_environment or {}).get("early_hook_risk", "Low") or "Low").upper()
    vol_upper = str(volatility or "").upper()
    if role_upper == "OPENER" or "HIGH" in vol_upper or env_hook == "HIGH":
        early_exit_risk = "High"
    elif role_upper == "BULK" or "MEDIUM" in vol_upper or env_hook == "MEDIUM":
        early_exit_risk = "Medium"
    else:
        early_exit_risk = "Low"

    under_candidate = original in ["LEAN UNDER", "UNDER", "STRONG UNDER"]
    under_shadow_only = False
    if under_candidate and role_upper in ["OPENER", "BULK"]:
        published = "PASS"
        under_shadow_only = True
        reasons.append(f"{role_upper.title()} pitcher Under remains shadow-only: {original} retained but not published")
    elif under_candidate and not nine_hitter_passed:
        published = "PASS"
        under_shadow_only = True
        reasons.append(f"Starter Under requires a confirmed nine-hitter batting order: {original} retained as shadow")
    elif under_candidate:
        reasons.append(f"Controlled starter Under publication passed for {original}")

    # Do not turn a valid play into PASS because one confirmed hitter lacks an
    # individual data profile. That hitter is represented by the team baseline.
    # The coverage value remains in metadata for transparency only.

    if published in ["LEAN OVER", "OVER", "STRONG OVER"] and role_upper == "STARTER":
        if not partial_workload_support:
            published = "PASS"
            reasons.append(f"Starter workload unsupported: {projected_pitches:.1f} pitches / {projected_bf:.1f} BF")
        elif not workload_supported:
            if published in ["OVER", "STRONG OVER"]:
                published = "LEAN OVER"
            reasons.append(f"Partial workload support: {projected_pitches:.1f} pitches / {projected_bf:.1f} BF; capped at Lean Over")

    if published == "STRONG OVER" and early_exit_risk in ["High", "Medium"]:
        published = "OVER"
        reasons.append(f"{early_exit_risk} early-exit risk prevents Strong Over")

    meta = {
        "published_grade": published,
        "shadow_grade": original,
        "grade_restriction_reason": " | ".join(reasons),
        "workload_support": ("FULL" if workload_supported else "PARTIAL" if partial_workload_support else "NO") if role_upper == "STARTER" else "ROLE-ADJUSTED",
        "nine_hitter_passed": _v15_5_bool_text(nine_hitter_passed),
        "lineup_profile_coverage": f"{hitters}/9 player profiles; missing slots use team baseline",
        "under_shadow_only": _v15_5_bool_text(under_shadow_only),
        "early_exit_risk": early_exit_risk,
    }
    return published, " | ".join(reasons), meta


