def _v162_logistic(value):
    value = float(value)
    if value >= 0:
        return 1.0 / (1.0 + math.exp(-value))
    exp_value = math.exp(value)
    return exp_value / (1.0 + exp_value)


def _v162_predict_locked_model(spec, values, lower, upper):
    eta = float(spec["intercept"])
    used = {}
    for name, coefficient in spec["coefficients"].items():
        raw = _safe_float_or_none((values or {}).get(name))
        if raw is None or not math.isfinite(float(raw)):
            raw = float(spec["means"][name])
            source = "training mean fallback"
        else:
            source = "observed"
        z_score = (float(raw) - float(spec["means"][name])) / max(
            1e-9, float(spec["stds"][name])
        )
        eta += float(coefficient) * z_score
        used[name] = {"value": float(raw), "z": float(z_score), "source": source}
    prediction = _v162_logistic(eta) if upper <= 1.0 else eta
    return max(float(lower), min(float(upper), float(prediction))), used


def _v162_rate_projection(values):
    return _v162_predict_locked_model(_V162_RATE_MODEL, values, 0.05, 0.50)


def _v162_power_prior(values):
    return _v162_predict_locked_model(_V162_POWER_PRIOR_MODEL, values, 0.08, 0.42)


def _v162_workload_projection(values):
    return _v162_predict_locked_model(_V162_WORKLOAD_MODEL, values, 8.0, 32.0)


def _v162_early_exit_projection(values):
    return _v162_predict_locked_model(_V162_EARLY_EXIT_MODEL, values, 0.02, 0.35)

