def _v16_team_split_inputs(opponent, pitcher_hand, team_batting_rhp, team_batting_lhp):
    """Return a handed team K/PA baseline without SO/AB inflation."""
    table = team_batting_lhp if str(pitcher_hand or "R").upper().startswith("L") else team_batting_rhp
    pa = _k15_float(get_value(table, "Teams", opponent, "Plate Appearances", 0), 0.0)
    if pa <= 0:
        ab = _k15_float(get_value(table, "Teams", opponent, "At Bats", 0), 0.0)
        bb = _k15_float(get_value(table, "Teams", opponent, "Walks", 0), 0.0)
        hbp = _k15_float(get_value(table, "Teams", opponent, "Hit By Pitch", 0), 0.0)
        sf = _k15_float(get_value(table, "Teams", opponent, "Sacrifice Flies", 0), 0.0)
        pa = ab + bb + hbp + sf
    strikeouts = _k15_float(get_value(table, "Teams", opponent, "Strikeouts", 0), 0.0)
    reported = _k15_rate(get_value(table, "Teams", opponent, "K%", 0), 0.0)
    raw_rate = reported if 0.04 <= reported <= 0.55 else (strikeouts / pa if pa > 0 else 0.22)
    if not 0.04 <= raw_rate <= 0.55:
        raw_rate = 0.22
    weight = pa / (pa + 200.0) if pa > 0 else 0.0
    stabilized = (weight * raw_rate) + ((1.0 - weight) * 0.22)
    return {
        "k_rate": max(0.10, min(0.42, stabilized)),
        "raw_k_rate": raw_rate,
        "pa": pa,
        "strikeouts": strikeouts,
        "sample_weight": weight,
        "source": "Handed team K/PA" if pa > 0 else "League K/PA fallback",
    }


def _team_baseline_k_rate_for_pitcher_hand(opponent, pitcher_hand, team_batting_rhp, team_batting_lhp):
    return _v16_team_split_inputs(
        opponent, pitcher_hand, team_batting_rhp, team_batting_lhp
    )["k_rate"]


def _k15_opponent_split_profile(opponent, pitcher_hand, team_batting_rhp, team_batting_lhp):
    profile = _v16_team_split_inputs(
        opponent, pitcher_hand, team_batting_rhp, team_batting_lhp
    )
    return {
        "overall_k_rate": profile["k_rate"],
        "split_k_rate": profile["k_rate"],
        "raw_split_k_rate": profile["raw_k_rate"],
        "split_pa": profile["pa"],
        "split_ab": "",
        "sample_weight": profile["sample_weight"],
        "rate_multiplier": 1.0,
        "source": profile["source"],
        "status": (
            f"V16.2 fallback team split: {profile['k_rate'] * 100:.1f}% K/PA "
            f"from {profile['pa']:.0f} PA; it is not multiplied into a confirmed-lineup projection."
        ),
    }


def _k15_pitcher_season_profile(pitcher, current, prior):
    """Hierarchically stabilize pitcher strikeouts per batter faced."""
    def one(frame):
        bf = _k15_float(get_value(frame, "Player", pitcher, "BF", 0), 0.0)
        ip = _k15_float(get_value(frame, "Player", pitcher, "IP", 0), 0.0)
        so = _k15_float(get_value(frame, "Player", pitcher, "SO", 0), 0.0)
        gs = _k15_float(
            get_value(frame, "Player", pitcher, "GS", get_value(frame, "Player", pitcher, "Games Started", 0)),
            0.0,
        )
        games = _k15_float(get_value(frame, "Player", pitcher, "G", 0), 0.0)
        pitches = _k15_float(get_value(frame, "Player", pitcher, "Pitches", 0), 0.0)
        bf_inferred = False
        if bf <= 0 and ip > 0:
            bf = ip * 4.30
            bf_inferred = True
        return {
            "bf": bf, "ip": ip, "so": so, "gs": gs, "g": games,
            "pitches": pitches, "bf_inferred": bf_inferred,
        }

    cur = one(current)
    prev = one(prior)
    league_rate = 0.22
    prior_rate = (
        (prev["so"] + league_rate * 150.0) / (prev["bf"] + 150.0)
        if prev["bf"] > 0 else league_rate
    )
    base_rate = (
        (cur["so"] + prior_rate * 120.0) / (cur["bf"] + 120.0)
        if cur["bf"] > 0 else prior_rate
    )
    ppbf = _k15_weighted([
        (cur["pitches"] / cur["bf"], min(cur["bf"], 500.0))
        if cur["pitches"] > 0 and cur["bf"] > 0 else (0, 0),
        (prev["pitches"] / prev["bf"], min(prev["bf"], 300.0) * 0.45)
        if prev["pitches"] > 0 and prev["bf"] > 0 else (0, 0),
    ])
    ppip = _k15_weighted([
        (cur["pitches"] / cur["ip"], min(cur["ip"], 120.0))
        if cur["pitches"] > 0 and cur["ip"] > 0 else (0, 0),
        (prev["pitches"] / prev["ip"], min(prev["ip"], 80.0) * 0.45)
        if prev["pitches"] > 0 and prev["ip"] > 0 else (0, 0),
    ])
    pps = _k15_weighted([
        (cur["pitches"] / cur["gs"], min(cur["gs"], 20.0))
        if cur["pitches"] > 0 and cur["gs"] > 0 else (0, 0),
        (prev["pitches"] / prev["gs"], min(prev["gs"], 12.0) * 0.45)
        if prev["pitches"] > 0 and prev["gs"] > 0 else (0, 0),
    ])
    return {
        "current": cur,
        "prior": prev,
        "base_k_rate": max(0.08, min(0.42, base_rate)),
        "current_k_rate": cur["so"] / cur["bf"] if cur["bf"] > 0 else None,
        "prior_stabilized_k_rate": prior_rate,
        "league_k_rate": league_rate,
        "pitches_per_bf": max(3.2, min(4.8, ppbf)) if ppbf is not None else None,
        "pitches_per_ip": max(13.0, min(20.5, ppip)) if ppip is not None else None,
        "pitches_per_start": max(35.0, min(115.0, pps)) if pps is not None else None,
        "pitches_available": ppbf is not None,
        "status": (
            f"Stabilized K/BF {base_rate * 100:.1f}%: current BF {cur['bf']:.0f}, "
            f"prior BF {prev['bf']:.0f}, current shrink 120 BF, prior shrink 150 BF."
        ),
    }


def _k15_pitcher_discipline_profile(pitcher, current, prior):
    """Expose real plate-discipline fields without turning defaults into skill."""
    metrics = {
        "whiff_pct": "Whiff %", "swing_pct": "Swing %",
        "called_strike_pct": "Called Strike %", "csw_pct": "CSW %",
        "chase_pct": "Chase %", "zone_contact_pct": "Zone Contact %",
        "chase_contact_pct": "Chase Contact %", "first_strike_pct": "First Strike %",
        "zone_pct": "Zone %", "edge_pct": "Edge %",
    }
    cur_bf = _k15_float(get_value(current, "Player", pitcher, "BF", 0), 0.0)
    prev_bf = _k15_float(get_value(prior, "Player", pitcher, "BF", 0), 0.0)
    out = {"source": "Observed pitcher discipline (diagnostic only)", "rate_multiplier": 1.0}
    available = []
    missing = []
    for key, column in metrics.items():
        cur_value = _k15_rate(get_value(current, "Player", pitcher, column, 0), 0.0)
        prev_value = _k15_rate(get_value(prior, "Player", pitcher, column, 0), 0.0)
        value = _k15_weighted([
            (cur_value, max(1.0, min(cur_bf, 500.0))) if cur_value > 0 else (0, 0),
            (prev_value, max(1.0, min(prev_bf, 300.0)) * 0.45) if prev_value > 0 else (0, 0),
        ])
        out[key] = value
        if value is None:
            missing.append(column)
        else:
            available.append(column)
    out.update({
        "available": bool(available),
        "available_metrics": available,
        "missing_metrics": missing,
        "status": (
            f"{len(available)}/{len(metrics)} pitcher-discipline fields observed; "
            "saved for diagnostics and AI review, not used as another K-rate multiplier."
        ),
    })
    return out


_v16_previous_team_discipline_profile = _k15_team_discipline_profile


def _k15_team_discipline_profile(team, year=MLB_SEASON):
    """Keep observed opponent discipline transparent and neutral when absent."""
    try:
        raw = dict(_v16_previous_team_discipline_profile(team, year) or {})
    except Exception as exc:
        raw = {"source": f"Unavailable ({exc})", "availability": "unavailable", "available": False}
    full = str(raw.get("availability", "")).lower() == "full" and bool(raw.get("available"))
    baseline_values = {
        "whiff_pct": 0.245, "zone_contact_pct": 0.825,
        "chase_contact_pct": 0.60, "chase_pct": 0.29,
        "first_strike_pct": 0.61, "called_strike_pct": 0.16,
        "csw_pct": 0.275, "pitches_per_pa": 3.90,
    }
    unavailable = []
    for key, baseline in baseline_values.items():
        value = _safe_float_or_none(raw.get(key))
        if not full or value is None or abs(float(value) - baseline) < 1e-9:
            raw[key] = None
            unavailable.append(key)
    raw["rate_multiplier"] = 1.0
    raw["missing_metrics"] = unavailable
    raw["status"] = (
        f"Opponent discipline: {len(baseline_values) - len(unavailable)}/{len(baseline_values)} "
        "observed fields; unavailable values remain blank and do not alter the projection."
    )
    return raw


@st.cache_data(ttl=300, show_spinner=False)
def _v16_historical_workload_profile(pitcher):
    """Estimate normal and early-exit BF regimes from completed starter rows."""
    neutral = {
        "sample": 0, "normal_sample": 0, "early_sample": 0,
        "normal_bf": 23.0, "early_bf": 14.0,
        "normal_bf_sd": 3.2, "early_bf_sd": 3.0,
        "early_exit_probability": 0.09,
        "normal_pitches": None, "early_pitches": None,
        "pitches_per_bf": None,
        "average_bf_l5": None, "previous_start_pitches": None,
        "bf_sd_l8": None, "stabilized_k_rate_l8": None,
        "recent_bf_l8": 0.0, "days_rest": None, "long_layoff": False,
        "source": "League starter workload prior",
        "status": "No completed pitcher workload rows; league starter workload prior is active.",
    }
    try:
        history = load_pitcher_recent_form()
    except Exception:
        return neutral
    if history is None or history.empty:
        return neutral
    frame = history.copy()
    for col in [
        "Pitcher", "Role", "Date", "Game Key", "Actual Ks",
        "Actual Batters Faced", "Actual Pitches", "Actual IP", "Early Exit",
    ]:
        if col not in frame.columns:
            frame[col] = ""
    target = normalize_name_for_match(pitcher)
    frame = frame[frame["Pitcher"].astype(str).apply(normalize_name_for_match) == target].copy()
    frame = frame[frame["Role"].astype(str).str.upper().eq("STARTER")].copy()
    frame["_date"] = pd.to_datetime(frame["Date"], errors="coerce")
    try:
        cutoff = pd.to_datetime(today_et_string())
    except Exception:
        cutoff = pd.to_datetime(str(date.today()))
    frame = frame[frame["_date"] < cutoff].copy()
    frame["_bf"] = pd.to_numeric(frame["Actual Batters Faced"], errors="coerce")
    frame["_ks"] = pd.to_numeric(frame["Actual Ks"], errors="coerce")
    frame["_pitches"] = pd.to_numeric(frame["Actual Pitches"], errors="coerce")
    frame["_ip"] = pd.to_numeric(frame["Actual IP"], errors="coerce")
    frame = frame[frame["_bf"] > 0].copy()
    if frame.empty:
        return neutral
    frame = frame.sort_values("_date", ascending=False)
    frame = frame.drop_duplicates(subset=["Date", "Game Key", "Pitcher", "Role"], keep="first").head(10)
    trailing8 = frame.head(8).copy()
    trailing5 = frame.head(5).copy()
    bf_values_l8 = trailing8["_bf"].dropna().astype(float).tolist()
    recent_bf_l8 = float(trailing8["_bf"].fillna(0.0).sum())
    recent_ks_l8 = float(trailing8["_ks"].fillna(0.0).sum())
    last_start_date = frame["_date"].dropna().max()
    days_rest = (
        int((cutoff.normalize() - last_start_date.normalize()).days)
        if pd.notna(last_start_date) else None
    )
    average_bf_l5 = (
        float(trailing5["_bf"].dropna().mean()) if not trailing5["_bf"].dropna().empty else None
    )
    previous_start_pitches = _safe_float_or_none(frame.iloc[0]["_pitches"]) if not frame.empty else None
    bf_sd_l8 = statistics.pstdev(bf_values_l8) if len(bf_values_l8) >= 2 else None
    stabilized_k_rate_l8 = (
        (recent_ks_l8 + 0.22 * 80.0) / (recent_bf_l8 + 80.0)
        if recent_bf_l8 > 0 and trailing8["_ks"].notna().any() else None
    )
    early_text = frame["Early Exit"].astype(str).str.upper().isin(["TRUE", "YES", "Y", "1"])
    frame["_early"] = early_text | (frame["_bf"] < 17.0) | (frame["_ip"] < 3.5)

    def recency_center(rows, column):
        values = pd.to_numeric(rows[column], errors="coerce").dropna().tolist()
        if not values:
            return None
        weights = [0.82 ** idx for idx in range(len(values))]
        return sum(float(value) * weight for value, weight in zip(values, weights)) / sum(weights)

    normal = frame[~frame["_early"]].copy()
    early = frame[frame["_early"]].copy()
    normal_raw = recency_center(normal, "_bf")
    normal_n = len(normal)
    normal_weight = normal_n / (normal_n + 4.0)
    normal_bf = (
        normal_weight * normal_raw + (1.0 - normal_weight) * 23.0
        if normal_raw is not None else 23.0
    )
    early_raw = recency_center(early, "_bf")
    early_n = len(early)
    early_weight = early_n / (early_n + 3.0)
    early_bf = (
        early_weight * early_raw + (1.0 - early_weight) * 14.0
        if early_raw is not None else 14.0
    )
    early_probability = (early_n + 0.09 * 12.0) / (len(frame) + 12.0)
    early_probability = max(0.04, min(0.24, early_probability))

    normal_pitches = recency_center(normal[normal["_pitches"] > 0], "_pitches")
    if normal_pitches is not None:
        pitch_weight = len(normal[normal["_pitches"] > 0]) / (len(normal[normal["_pitches"] > 0]) + 4.0)
        normal_pitches = pitch_weight * normal_pitches + (1.0 - pitch_weight) * 89.0
    early_pitches = recency_center(early[early["_pitches"] > 0], "_pitches")
    ppbf_rows = frame[(frame["_pitches"] > 0) & (frame["_bf"] > 0)].copy()
    ppbf_rows["_ppbf"] = ppbf_rows["_pitches"] / ppbf_rows["_bf"]
    ppbf = recency_center(ppbf_rows, "_ppbf")
    normal_sd = statistics.pstdev(normal["_bf"].astype(float).tolist()) if normal_n >= 2 else 3.2
    early_sd = statistics.pstdev(early["_bf"].astype(float).tolist()) if early_n >= 2 else 3.0
    return {
        "sample": len(frame), "normal_sample": normal_n, "early_sample": early_n,
        "normal_bf": max(18.0, min(29.0, normal_bf)),
        "early_bf": max(8.0, min(18.0, early_bf)),
        "normal_bf_sd": max(2.4, min(4.8, normal_sd)),
        "early_bf_sd": max(2.0, min(4.5, early_sd)),
        "early_exit_probability": early_probability,
        "normal_pitches": max(70.0, min(110.0, normal_pitches)) if normal_pitches is not None else None,
        "early_pitches": max(25.0, min(85.0, early_pitches)) if early_pitches is not None else None,
        "pitches_per_bf": max(3.2, min(4.8, ppbf)) if ppbf is not None else None,
        "average_bf_l5": average_bf_l5,
        "previous_start_pitches": previous_start_pitches,
        "bf_sd_l8": bf_sd_l8,
        "stabilized_k_rate_l8": stabilized_k_rate_l8,
        "recent_bf_l8": recent_bf_l8,
        "days_rest": days_rest,
        "long_layoff": bool(days_rest is not None and days_rest > 14),
        "source": "Completed pitcher starter workload rows + league shrinkage",
        "status": (
            f"Workload history: {len(frame)} starts ({normal_n} normal, {early_n} early); "
            f"normal {normal_bf:.1f} BF, early {early_bf:.1f} BF, "
            f"early-exit probability {early_probability * 100:.1f}%."
        ),
    }


def _v162_first_observed(*values):
    for value in values:
        observed = _safe_float_or_none(value)
        if observed is not None and math.isfinite(float(observed)):
            return observed
    return None


def _v162_workload_from_components(
    history, season_profile, discipline, recent_pitch=None,
    lineup_pitches_pa=None, role_context=None,
):
    history = dict(history or {})
    recent_pitch = dict(recent_pitch or {})
    role_context = dict(role_context or {})
    role_bf = _v162_first_observed(role_context.get("role_bf"), 22.60)

    average_bf_l5 = _v162_first_observed(
        recent_pitch.get("average_bf_l5"), history.get("average_bf_l5"), role_bf,
    )
    previous_start_pitches = _v162_first_observed(
        recent_pitch.get("previous_start_pitches"), history.get("previous_start_pitches"),
        season_profile.get("pitches_per_start"), 87.62,
    )
    observed_lineup_pppa = _safe_float_or_none(lineup_pitches_pa)
    if observed_lineup_pppa is None:
        observed_lineup_pppa = _safe_float_or_none((discipline or {}).get("pitches_per_pa"))
    if observed_lineup_pppa is not None and not 3.20 <= observed_lineup_pppa <= 4.65:
        observed_lineup_pppa = None
    groundball_l8 = _v162_first_observed(
        recent_pitch.get("groundball_rate_l8"),
        _V162_WORKLOAD_MODEL["means"]["pit_groundball_l8"],
    )
    bf_sd_l8 = _v162_first_observed(
        recent_pitch.get("bf_sd_l8"), history.get("bf_sd_l8"), 2.76,
    )
    days_rest = _v162_first_observed(recent_pitch.get("days_rest"), history.get("days_rest"))
    long_layoff = 1.0 if days_rest is not None and days_rest > 14.0 else 0.0

    values = {
        "long_layoff": long_layoff,
        "pit_avg_bf_l5": average_bf_l5,
        "lineup_pitches_pa": observed_lineup_pppa,
        "pit_prev_pitches": previous_start_pitches,
        "pit_groundball_l8": groundball_l8,
    }
    regression_bf, workload_inputs = _v162_workload_projection(values)
    early_probability, early_inputs = _v162_early_exit_projection({
        "long_layoff": long_layoff,
        "pit_avg_bf_l5": average_bf_l5,
    })

    early_bf = max(8.0, min(18.0, _k15_float(history.get("early_bf"), 14.0)))
    normal_bf = (
        (regression_bf - early_probability * early_bf) / max(0.65, 1.0 - early_probability)
    )
    normal_bf = max(18.0, min(30.0, normal_bf))
    expected_bf = (1.0 - early_probability) * normal_bf + early_probability * early_bf

    ppbf = _v162_first_observed(history.get("pitches_per_bf"), season_profile.get("pitches_per_bf"))
    normal_pitches = _safe_float_or_none(history.get("normal_pitches"))
    history_normal_bf = _safe_float_or_none(history.get("normal_bf"))
    if normal_pitches is not None and history_normal_bf and history_normal_bf > 0:
        normal_pitches *= normal_bf / history_normal_bf
    elif ppbf is not None:
        normal_pitches = normal_bf * ppbf
    elif previous_start_pitches is not None and average_bf_l5 and average_bf_l5 > 0:
        normal_pitches = previous_start_pitches * normal_bf / average_bf_l5
    early_pitches = _safe_float_or_none(history.get("early_pitches"))
    if early_pitches is None and ppbf is not None:
        early_pitches = early_bf * ppbf
    elif early_pitches is None and normal_pitches is not None and normal_bf > 0:
        early_pitches = normal_pitches * early_bf / normal_bf
    projected_pitches = (
        (1.0 - early_probability) * normal_pitches + early_probability * early_pitches
        if normal_pitches is not None and early_pitches is not None else None
    )
    projected_ppbf = projected_pitches / expected_bf if projected_pitches is not None and expected_bf > 0 else None

    historical_normal_sd = _v162_first_observed(history.get("normal_bf_sd"), 3.2)
    # BF volatility changes distribution width, not the fitted BF mean.
    volatility_sd = max(2.0, min(5.5, float(bf_sd_l8 or 2.76)))
    normal_sd = max(2.2, min(5.2, 0.65 * historical_normal_sd + 0.35 * volatility_sd))
    early_sd = max(2.0, min(4.5, _k15_float(history.get("early_bf_sd"), 3.0)))
    mean_variance = (
        (1.0 - early_probability) * (normal_sd ** 2 + (normal_bf - expected_bf) ** 2)
        + early_probability * (early_sd ** 2 + (early_bf - expected_bf) ** 2)
    )
    bf_std = math.sqrt(max(1.0, mean_variance))
    expected_ip = max(2.5, min(7.0, expected_bf / 4.30))
    tto3 = 1.0 / (1.0 + math.exp(-(normal_bf - 19.5) / 2.2))
    early_risk = "Low" if early_probability <= 0.07 else "Medium" if early_probability <= 0.14 else "High"
    pp_source = "confirmed-lineup weighted" if _safe_float_or_none(lineup_pitches_pa) is not None else "team/fallback"
    return {
        "projected_start_ip": round(expected_ip, 2),
        "projected_pitches": round(projected_pitches, 1) if projected_pitches is not None else "",
        "projected_bf": round(expected_bf, 2),
        "regression_expected_bf": round(regression_bf, 3),
        "normal_bf": round(normal_bf, 2), "early_bf": round(early_bf, 2),
        "normal_bf_sd": round(normal_sd, 2), "early_bf_sd": round(early_sd, 2),
        "early_exit_probability": round(early_probability, 4),
        "early_exit_risk": early_risk,
        "normal_pitches": round(normal_pitches, 1) if normal_pitches is not None else "",
        "early_pitches": round(early_pitches, 1) if early_pitches is not None else "",
        "pitcher_pitches_per_bf": round(ppbf, 3) if ppbf is not None else "",
        "opponent_pitches_per_pa": round(observed_lineup_pppa, 3) if observed_lineup_pppa is not None else "",
        "lineup_pitches_per_pa": round(observed_lineup_pppa, 3) if observed_lineup_pppa is not None else "",
        "lineup_pitches_pa_source": pp_source,
        "projected_pitches_per_bf": round(projected_ppbf, 3) if projected_ppbf is not None else "",
        "third_time_probability": round(tto3, 4),
        "workload_pressure_score": round(early_probability / 0.09, 2),
        "bf_std": round(bf_std, 2), "bf_volatility_l8": round(volatility_sd, 3),
        "current_role": role_context.get("current_role", "Starter"),
        "prior_role": role_context.get("prior_role", "Starter"),
        "hybrid_or_reliever": bool(role_context.get("hybrid_or_reliever", False)),
        "opponent_leash": {}, "history": history,
        "regression_inputs": workload_inputs,
        "early_exit_inputs": early_inputs,
        "status": (
            f"V16.2 regression workload {regression_bf:.1f} BF: "
            f"{(1.0 - early_probability) * 100:.1f}% normal ({normal_bf:.1f} BF) + "
            f"{early_probability * 100:.1f}% early exit ({early_bf:.1f} BF) = "
            f"{expected_bf:.1f} expected BF; {pp_source} pitches/PA; BF volatility {volatility_sd:.2f}."
        ),
    }


def _k15_workload_projection(
    pitcher, opponent, season_profile, base_k_rate, current, prior,
    team_batting_rhp, team_batting_lhp, discipline,
    recent_pitch=None, lineup_pitches_pa=None,
):
    history = _v16_historical_workload_profile(pitcher)
    try:
        base_ip, cur_role, prior_role, hybrid = _blended_pitcher_start_ip(pitcher, current, prior)
    except Exception:
        base_ip, cur_role, prior_role, hybrid = 5.35, "Starter", "Starter", False
    role_context = {
        "role_bf": max(18.0, min(29.0, _k15_float(base_ip, 5.35) * 4.30)),
        "current_role": cur_role, "prior_role": prior_role,
        "hybrid_or_reliever": bool(hybrid),
    }
    return _v162_workload_from_components(
        history, season_profile, discipline, recent_pitch=recent_pitch,
        lineup_pitches_pa=lineup_pitches_pa, role_context=role_context,
    )


def _v16_discrete_normal_weights(mean, sd, minimum, maximum):
    mean = float(mean)
    sd = max(0.75, float(sd))
    weights = {}
    for value in range(int(minimum), int(maximum) + 1):
        weight = math.exp(-0.5 * ((value - mean) / sd) ** 2)
        weights[value] = weight
    total = sum(weights.values())
    return {value: weight / total for value, weight in weights.items()} if total > 0 else {int(round(mean)): 1.0}


def _v16_beta_binomial_probability(k, n, probability, concentration=120.0):
    if k < 0 or k > n:
        return 0.0
    p = max(0.01, min(0.60, float(probability)))
    alpha = p * concentration
    beta = (1.0 - p) * concentration
    log_probability = (
        math.lgamma(n + 1.0) - math.lgamma(k + 1.0) - math.lgamma(n - k + 1.0)
        + math.lgamma(k + alpha) + math.lgamma(n - k + beta) - math.lgamma(n + alpha + beta)
        - math.lgamma(alpha) - math.lgamma(beta) + math.lgamma(alpha + beta)
    )
    return math.exp(log_probability)


def _v162_logit(probability):
    probability = max(1e-6, min(1.0 - 1e-6, float(probability)))
    return math.log(probability / (1.0 - probability))


def _v162_shift_probabilities(probabilities, target_rate, weights=None):
    """Apply one common logit shift while preserving hitter differences."""
    values = [max(0.01, min(0.60, float(value))) for value in probabilities]
    if not values:
        return []
    target = max(0.01, min(0.60, float(target_rate)))
    if weights is None or len(weights) != len(values):
        weights = [1.0] * len(values)
    weights = [max(0.0, float(value)) for value in weights]
    if sum(weights) <= 0:
        weights = [1.0] * len(values)

    def weighted_rate(offset):
        shifted = [_v162_logistic(_v162_logit(value) + offset) for value in values]
        return sum(weight * value for weight, value in zip(weights, shifted)) / sum(weights)

    low, high = -8.0, 8.0
    for _ in range(64):
        middle = (low + high) / 2.0
        if weighted_rate(middle) < target:
            low = middle
        else:
            high = middle
    offset = (low + high) / 2.0
    return [max(0.01, min(0.60, _v162_logistic(_v162_logit(value) + offset))) for value in values]


def _v162_poisson_binomial(probabilities):
    """Exact K-count PMF for repeated, non-identical batter encounters."""
    pmf = [1.0]
    for probability in probabilities:
        probability = max(0.0, min(1.0, float(probability)))
        updated = [0.0] * (len(pmf) + 1)
        for strikeouts, mass in enumerate(pmf):
            updated[strikeouts] += mass * (1.0 - probability)
            updated[strikeouts + 1] += mass * probability
        pmf = updated
    return {strikeouts: mass for strikeouts, mass in enumerate(pmf) if mass > 0.0}


def _v163_binomial_pmf(number_pa, probability):
    """Exact independent-PA batter K-count PMF; expected counts are never capped at one."""
    number_pa = max(0, int(number_pa))
    probability = max(1e-9, min(1.0 - 1e-9, float(probability)))
    return {
        strikeouts: (
            math.comb(number_pa, strikeouts)
            * (probability ** strikeouts)
            * ((1.0 - probability) ** (number_pa - strikeouts))
        )
        for strikeouts in range(number_pa + 1)
    }


def _v163_baseline_multi_probability(number_pa, probability):
    pmf = _v163_binomial_pmf(number_pa, probability)
    return sum(mass for strikeouts, mass in pmf.items() if strikeouts >= 2)


def _v163_calibrated_multi_probability(number_pa, probability):
    """Locked replicated P(2+) calibration, bounded to a mean-feasible tail."""
    number_pa = max(0, int(number_pa))
    if number_pa < 2:
        return 0.0
    probability = max(1e-9, min(1.0 - 1e-9, float(probability)))
    baseline = max(1e-8, min(1.0 - 1e-8, _v163_baseline_multi_probability(number_pa, probability)))
    baseline_logit = _v162_logit(baseline)
    spec = _V163_MULTI_K_TAIL_MODEL
    z_score = (baseline_logit - float(spec["mean"])) / max(1e-9, float(spec["std"]))
    calibrated = _v162_logistic(
        baseline_logit + float(spec["intercept"]) + float(spec["coefficient"]) * z_score
    )

    # Given mean mu and support {0, ..., n}, P(K>=2) must lie in this interval.
    # These bounds make the later PMF tilt mathematically possible without ever
    # moving the original expected strikeout count.
    mean = number_pa * probability
    minimum = max(0.0, (mean - 1.0) / max(1.0, number_pa - 1.0))
    maximum = min(1.0, mean / 2.0)
    if maximum <= minimum + 1e-12:
        return max(0.0, min(1.0, (minimum + maximum) / 2.0))
    epsilon = min(1e-8, (maximum - minimum) * 1e-5)
    return max(minimum + epsilon, min(maximum - epsilon, calibrated))


def _v163_mean_preserving_batter_pmf(number_pa, probability, target_tail=None):
    """Reshape 0/1/2/3+ mass to P(2+) while retaining n*p exactly.

    Fixing the tail mass leaves one common count tilt to solve. The low group
    (0/1) and tail group (2+) are normalized separately, reducing the constrained
    exponential-family solution to one monotonic bisection.
    """
    number_pa = max(0, int(number_pa))
    base = _v163_binomial_pmf(number_pa, probability)
    if number_pa < 2:
        return base
    probability = max(1e-9, min(1.0 - 1e-9, float(probability)))
    mean = number_pa * probability
    target = (
        _v163_calibrated_multi_probability(number_pa, probability)
        if target_tail is None else float(target_tail)
    )
    minimum = max(0.0, (mean - 1.0) / max(1.0, number_pa - 1.0))
    maximum = min(1.0, mean / 2.0)
    if maximum <= minimum + 1e-12:
        return base
    epsilon = min(1e-8, (maximum - minimum) * 1e-5)
    target = max(minimum + epsilon, min(maximum - epsilon, target))
    low_values = [0, 1]
    tail_values = list(range(2, number_pa + 1))

    def group_weights(values, tilt):
        logs = [math.log(max(1e-300, base[value])) + tilt * value for value in values]
        center = max(logs)
        weights = [math.exp(value - center) for value in logs]
        total = sum(weights)
        return [value / total for value in weights]

    def adjusted_mean(tilt):
        low_weights = group_weights(low_values, tilt)
        tail_weights = group_weights(tail_values, tilt)
        return (
            (1.0 - target) * sum(value * mass for value, mass in zip(low_values, low_weights))
            + target * sum(value * mass for value, mass in zip(tail_values, tail_weights))
        )

    low, high = -30.0, 30.0
    for _ in range(64):
        middle = (low + high) / 2.0
        if adjusted_mean(middle) < mean:
            low = middle
        else:
            high = middle
    tilt = (low + high) / 2.0
    low_weights = group_weights(low_values, tilt)
    tail_weights = group_weights(tail_values, tilt)
    adjusted = {
        value: (1.0 - target) * mass for value, mass in zip(low_values, low_weights)
    }
    adjusted.update({value: target * mass for value, mass in zip(tail_values, tail_weights)})
    total = sum(adjusted.values())
    return {value: mass / total for value, mass in adjusted.items()}


def _v163_convolve_pmfs(left, right):
    combined = {}
    for left_count, left_mass in (left or {}).items():
        for right_count, right_mass in (right or {}).items():
            count = int(left_count) + int(right_count)
            combined[count] = combined.get(count, 0.0) + float(left_mass) * float(right_mass)
    return combined


def _v163_pa_counts_by_order(batters_faced):
    batters_faced = max(0, int(batters_faced))
    return [
        0 if batters_faced < order else 1 + ((batters_faced - order) // 9)
        for order in range(1, 10)
    ]


def _v163_pmf_summary(pmf):
    if not pmf:
        return {"mode": None, "median": None, "mean": None, "std": None}
    total = sum(float(value) for value in pmf.values())
    normalized = {int(key): float(value) / total for key, value in pmf.items()} if total > 0 else {}
    if not normalized:
        return {"mode": None, "median": None, "mean": None, "std": None}
    mode = max(sorted(normalized), key=lambda value: normalized[value])
    cumulative = 0.0
    median = max(normalized)
    for value in sorted(normalized):
        cumulative += normalized[value]
        if cumulative >= 0.50:
            median = value
            break
    mean = sum(value * mass for value, mass in normalized.items())
    variance = sum(((value - mean) ** 2) * mass for value, mass in normalized.items())
    return {
        "mode": int(mode), "median": int(median), "mean": float(mean),
        "std": math.sqrt(max(0.0, variance)),
    }


def _v16_distribution_expected_bf(details):
    data = details or {}
    early_probability = max(0.0, min(1.0, _k15_float(data.get("early_exit_probability"), 0.09)))
    normal_bf = _k15_float(data.get("normal_bf_mean", data.get("normal_bf", 23.0)), 23.0)
    early_bf = _k15_float(data.get("early_bf_mean", data.get("early_bf", 14.0)), 14.0)
    return (1.0 - early_probability) * normal_bf + early_probability * early_bf


def _v16_k_count_pmf(distribution_details):
    data = distribution_details or {}
    k_rate = _safe_float_or_none(data.get("k_rate"))
    if k_rate is None or not 0.01 <= k_rate <= 0.60:
        return {}
    early_probability = max(0.0, min(0.35, _k15_float(data.get("early_exit_probability"), 0.09)))
    normal_bf = _k15_float(data.get("normal_bf_mean", data.get("normal_bf", 23.0)), 23.0)
    early_bf = _k15_float(data.get("early_bf_mean", data.get("early_bf", 14.0)), 14.0)
    normal_sd = _k15_float(data.get("normal_bf_sd"), 3.2)
    early_sd = _k15_float(data.get("early_bf_sd"), 3.0)
    normal_weights = _v16_discrete_normal_weights(normal_bf, normal_sd, 10, 36)
    early_weights = _v16_discrete_normal_weights(early_bf, early_sd, 3, 25)
    raw_batter_probabilities = data.get("batter_probabilities", [])
    batter_probabilities = []
    if isinstance(raw_batter_probabilities, (list, tuple)):
        for item in raw_batter_probabilities:
            value = item.get("probability") if isinstance(item, dict) else item
            parsed = _safe_float_or_none(value)
            if parsed is not None:
                batter_probabilities.append(max(0.01, min(0.60, parsed)))
    if len(batter_probabilities) != 9:
        batter_probabilities = []
    regimes = [
        (1.0 - early_probability, normal_weights),
        (early_probability, early_weights),
    ]
    exposure_weights = [0.0] * 9
    discrete_expected_bf = 0.0
    for regime_probability, bf_weights in regimes:
        for batters_faced, bf_probability in bf_weights.items():
            scenario_probability = regime_probability * bf_probability
            counts = _v163_pa_counts_by_order(batters_faced)
            discrete_expected_bf += scenario_probability * int(batters_faced)
            for index, count in enumerate(counts):
                exposure_weights[index] += scenario_probability * count
    target_mean = _safe_float_or_none(data.get("projection", data.get("target_mean")))
    target_rate = (
        max(0.01, min(0.60, target_mean / discrete_expected_bf))
        if target_mean is not None and discrete_expected_bf > 0 else k_rate
    )
    if batter_probabilities:
        batter_probabilities = _v162_shift_probabilities(
            batter_probabilities, target_rate, weights=exposure_weights
        )

    pmf = {}
    conditional_cache = {}
    batter_pmf_cache = {}
    for regime_probability, bf_weights in regimes:
        for batters_faced, bf_probability in bf_weights.items():
            if batters_faced not in conditional_cache:
                if batter_probabilities:
                    # Build one 0/1/2/3+ distribution per hitter, then convolve
                    # all nine. Each batter PMF preserves n*p, so the pitcher's
                    # true mean is unchanged while replicated multi-K behavior
                    # changes the market tails.
                    hitter_total = {0: 1.0}
                    for index, (number_pa, probability) in enumerate(zip(
                        _v163_pa_counts_by_order(batters_faced), batter_probabilities
                    )):
                        cache_key = (index, int(number_pa), round(float(probability), 12))
                        if cache_key not in batter_pmf_cache:
                            batter_pmf_cache[cache_key] = _v163_mean_preserving_batter_pmf(
                                number_pa, probability
                            )
                        hitter_total = _v163_convolve_pmfs(
                            hitter_total, batter_pmf_cache[cache_key]
                        )
                    conditional_cache[batters_faced] = hitter_total
                else:
                    conditional_cache[batters_faced] = {
                        strikeouts: _v16_beta_binomial_probability(strikeouts, batters_faced, target_rate)
                        for strikeouts in range(batters_faced + 1)
                    }
            for strikeouts, event_probability in conditional_cache[batters_faced].items():
                pmf[strikeouts] = pmf.get(strikeouts, 0.0) + regime_probability * bf_probability * event_probability
    total = sum(pmf.values())
    return {strikeouts: probability / total for strikeouts, probability in pmf.items()} if total > 0 else {}


def _v16_pmf_moments(pmf):
    if not pmf:
        return None, None
    mean = sum(float(value) * probability for value, probability in pmf.items())
    variance = sum(((float(value) - mean) ** 2) * probability for value, probability in pmf.items())
    return mean, math.sqrt(max(0.0, variance))


def _v162_pitcher_rate_components(season_profile, workload, recent_pitch):
    history = dict((workload or {}).get("history", {}) or {})
    recent_pitch = dict(recent_pitch or {})
    pitcher_k_rate = _v162_first_observed(
        recent_pitch.get("stabilized_k_rate_l8"),
        history.get("stabilized_k_rate_l8"),
        season_profile.get("base_k_rate"),
        0.22,
    )
    recent_bf = max(
        _k15_float(recent_pitch.get("recent_bf_l8"), 0.0),
        _k15_float(history.get("recent_bf_l8"), 0.0),
    )
    return {
        "pitcher_k_rate": max(0.08, min(0.42, pitcher_k_rate)),
        "recent_bf": max(0.0, recent_bf),
        "whiff_rate": _safe_float_or_none(recent_pitch.get("whiff_rate_l8")),
        "fastball_velocity": _safe_float_or_none(recent_pitch.get("fastball_velocity_l8")),
        "release_extension": _safe_float_or_none(recent_pitch.get("release_extension_l8")),
    }


def _v162_target_k_rate(lineup_k_rate, pitcher_hand, pitcher_is_home, season_profile, workload, recent_pitch):
    components = _v162_pitcher_rate_components(season_profile, workload, recent_pitch)
    rate_values = {
        "lineup_k_rate": lineup_k_rate,
        "pit_k_rate_l8": components["pitcher_k_rate"],
        "pit_fastball_velo_l8": components["fastball_velocity"],
        "home_pitcher": pitcher_is_home,
        "pit_release_extension_l8": components["release_extension"],
        "pitcher_left": 1.0 if str(pitcher_hand or "R").upper().startswith("L") else 0.0,
    }
    production_rate, production_inputs = _v162_rate_projection(rate_values)
    prior_values = {
        "pit_whiff_l8": components["whiff_rate"],
        "pit_fastball_velo_l8": components["fastball_velocity"],
        "pit_release_extension_l8": components["release_extension"],
    }
    available_prior_traits = sum(
        parsed is not None and math.isfinite(float(parsed))
        for parsed in (_safe_float_or_none(value) for value in prior_values.values())
    )
    prior_weight = (
        max(0.0, min(1.0, (80.0 - components["recent_bf"]) / 80.0))
        if available_prior_traits >= 2 else 0.0
    )
    mechanism_pitcher_rate, prior_inputs = _v162_power_prior(prior_values)
    mechanism_matchup_rate = _k16_log5_strikeout_probability(
        mechanism_pitcher_rate, lineup_k_rate, 0.22
    )
    target_rate = (
        (1.0 - prior_weight) * production_rate + prior_weight * mechanism_matchup_rate
    )
    return max(0.05, min(0.50, target_rate)), {
        "production_rate": production_rate,
        "production_inputs": production_inputs,
        "power_prior_rate": mechanism_pitcher_rate,
        "power_prior_matchup_rate": mechanism_matchup_rate,
        "power_prior_inputs": prior_inputs,
        "power_prior_weight": prior_weight,
        "recent_bf": components["recent_bf"],
        "pitcher_k_rate_l8": components["pitcher_k_rate"],
        "fastball_velocity_l8": components["fastball_velocity"],
        "release_extension_l8": components["release_extension"],
        "whiff_rate_l8": components["whiff_rate"],
    }


def expected_strikeouts(pitcher, opponent, pitcher_this_year, pitcher_last_year, team_batting_rhp, team_batting_lhp, pitcher_arsenal_df=None, team_pitch_type_df=None, return_details=False):
    season = _k15_pitcher_season_profile(pitcher, pitcher_this_year, pitcher_last_year)
    hand = get_value(pitcher_this_year, "Player", pitcher, "Throws", None)
    if hand in [None, ""]:
        hand = get_value(pitcher_last_year, "Player", pitcher, "Throws", "R")
    split = _k15_opponent_split_profile(opponent, hand, team_batting_rhp, team_batting_lhp)
    discipline = _k15_team_discipline_profile(opponent, MLB_SEASON)
    pitcher_skill = _k15_pitcher_discipline_profile(pitcher, pitcher_this_year, pitcher_last_year)
    recent_pitch = _k15_recent_pitch_profile(pitcher, pitcher_this_year, pitcher_last_year)
    recent_pitch = dict(recent_pitch or {})
    recent_pitch["diagnostic_rate_multiplier"] = recent_pitch.get("rate_multiplier", 1.0)
    recent_pitch["rate_multiplier"] = 1.0
    arsenal = dict(pitch_type_arsenal_adjustment(
        pitcher, opponent, pitcher_arsenal_df, team_pitch_type_df
    ) or {})
    arsenal["diagnostic_k_rate_multiplier"] = arsenal.get("k_rate_multiplier", 1.0)
    arsenal["k_rate_multiplier"] = 1.0

    fallback_hitter_rate = split["split_k_rate"]
    workload = _k15_workload_projection(
        pitcher, opponent, season, season["base_k_rate"], pitcher_this_year, pitcher_last_year,
        team_batting_rhp, team_batting_lhp, discipline,
        recent_pitch=recent_pitch,
    )
    base_rate = _v162_pitcher_rate_components(season, workload, recent_pitch)["pitcher_k_rate"]
    # Location is unknown until the confirmed batting side is loaded. Use the
    # training mean here; the batter-by-batter pass supplies the real home flag.
    matchup_rate, regression_rate = _v162_target_k_rate(
        fallback_hitter_rate, hand, None, season, workload, recent_pitch
    )
    projected_bf = _k15_float(workload.get("projected_bf"), 22.0)
    projection = projected_bf * matchup_rate
    six_ip_projection = 25.8 * matchup_rate
    distribution = {
        "architecture": "V16.3 regression true mean with BF mixture fallback",
        "early_exit_probability": workload.get("early_exit_probability", 0.09),
        "normal_bf_mean": workload.get("normal_bf", 23.0),
        "normal_bf_sd": workload.get("normal_bf_sd", 3.2),
        "early_bf_mean": workload.get("early_bf", 14.0),
        "early_bf_sd": workload.get("early_bf_sd", 3.0),
        "expected_bf": projected_bf,
        "k_rate": matchup_rate,
        "source": "Team K/PA fallback pending confirmed batter-level projection",
    }
    _, structural_std = _v16_pmf_moments(_v16_k_count_pmf(distribution))
    structural_std = max(1.75, min(3.30, structural_std if structural_std is not None else 2.10))
    rate_multipliers = {
        "team_split": 1.0, "arsenal": 1.0, "pitcher_skill": 1.0,
        "opponent_discipline": 1.0, "recent_pitch": 1.0,
    }
    arsenal.update({
        "base_projection": round(projected_bf * base_rate, 2),
        "adjusted_projection": round(projection, 2),
        "six_ip_projection": round(six_ip_projection, 2),
        "ip_scale": round(_k15_float(workload.get("projected_start_ip"), 0.0) / 6.0, 3),
        "workload": workload,
        "opponent_leash": {},
        "projection_architecture": K_MODEL_ARCHITECTURE,
        "season_profile": season,
        "base_k_rate": round(base_rate, 5),
        "team_split_k_rate": round(fallback_hitter_rate, 5),
        "matchup_k_rate": round(matchup_rate, 5),
        "rate_multipliers": rate_multipliers,
        "pitcher_discipline": pitcher_skill,
        "opponent_discipline": discipline,
        "recent_pitch_profile": recent_pitch,
        "regression_target_k_rate": round(matchup_rate, 5),
        "regression_rate_details": regression_rate,
        "power_prior_weight": round(regression_rate.get("power_prior_weight", 0.0), 4),
        "fastball_velocity_input": regression_rate.get("fastball_velocity_l8", ""),
        "release_extension_input": regression_rate.get("release_extension_l8", ""),
        "structural_std": round(structural_std, 3),
        "k_distribution": distribution,
        "under_support_count": 0,
        "under_support_notes": [],
        "modifier": 0.0,
        "status": (
            f"V16.2 fallback: locked regression target {matchup_rate * 100:.1f}% K/BF "
            f"from pitcher {base_rate * 100:.1f}% K/BF and opponent "
            f"{fallback_hitter_rate * 100:.1f}% K/PA; power-prior weight "
            f"{regression_rate.get('power_prior_weight', 0.0) * 100:.0f}%. "
            f"{workload.get('status', '')} Confirmed lineup replaces the fallback "
            "with nine repeated batter probabilities."
        ),
    })
    if return_details:
        return max(0.0, projection), arsenal
    return max(0.0, projection)


def six_inning_strikeouts(pitcher, opponent, pitcher_this_year, pitcher_last_year, team_batting_rhp, team_batting_lhp, pitcher_arsenal_df=None, team_pitch_type_df=None, return_details=False, game_location="neutral", umpire_context=None):
    _, details = expected_strikeouts(
        pitcher, opponent, pitcher_this_year, pitcher_last_year,
        team_batting_rhp, team_batting_lhp, pitcher_arsenal_df, team_pitch_type_df,
        return_details=True,
    )
    value = _k15_float(details.get("six_ip_projection"), 0.0)
    if return_details:
        clone = dict(details)
        clone["base_projection"] = round(25.8 * _k15_float(details.get("base_k_rate"), 0.22), 2)
        clone["adjusted_projection"] = round(value, 2)
        return value, clone
    return value


def _k16_individual_arsenal_multiplier(player_name, pitch_type_matchup):
    """Retain hitter pitch-mix output for diagnostics without changing K rate."""
    rows = (pitch_type_matchup or {}).get("detail_rows", pd.DataFrame())
    if not isinstance(rows, pd.DataFrame) or rows.empty or "Player" not in rows.columns:
        return 1.0, "Pitch-type data unavailable; regression projection unchanged", None
    temp = rows.copy()
    temp["_name_key"] = temp["Player"].apply(normalize_name_for_match)
    match = temp[temp["_name_key"].isin(_name_keys(player_name))]
    if match.empty:
        return 1.0, "No individual pitch-type row; regression projection unchanged", None
    row = match.iloc[0]
    source = str(row.get("Source", "") or "")
    sample = max(
        _k15_float(row.get("PA", 0), 0.0),
        _k15_float(row.get("AB", 0), 0.0),
        _k15_float(row.get("Sample", 0), 0.0),
    )
    matched_pitches = _k15_float(row.get("Pitches Matched", row.get("Matched Pitches", 0)), 0.0)
    score = _safe_float_or_none(row.get("Arsenal Score"))
    if source.lower() != "hitter" or sample < 50 or (matched_pitches > 0 and matched_pitches < 2) or score is None:
        return 1.0, "Individual pitch-type diagnostic only", score
    return 1.0, "Observed pitch-type matchup retained as diagnostic only", score


def _k16_build_batter_matchup_details(
    lineup, base_details, pitcher_profile_details, pitcher_hand, pitcher_is_home=None,
):
    neutral = {
        "active": False, "projection_multiplier": 1.0,
        "six_ip_projection_multiplier": 1.0, "matchup_rate": None,
        "six_ip_matchup_rate": None, "expected_ks": None,
        "six_ip_expected_ks": None, "hitters": 0, "split_hitters": 0,
        "confirmed_lineup_count": len(lineup or []), "fallback_slots": 9,
        "coverage": 0.0, "rows": pd.DataFrame(), "batter_probabilities": [],
        "regression_target_k_rate": None, "power_prior_weight": 0.0,
        "lineup_pitches_per_pa": None, "max_batter_expected_ks": 0.0,
        "status": "V16.3 batter-by-batter tail engine unavailable.",
    }
    if not lineup or len(lineup) < 8 or not isinstance(pitcher_profile_details, dict):
        neutral["status"] = (
            f"V16.3 requires at least 8 confirmed batting-order entries; {len(lineup or [])} were found."
        )
        return neutral
    base_rate = _k15_float(pitcher_profile_details.get("base_k_rate"), 0.0)
    workload = pitcher_profile_details.get("workload", {}) or {}
    projected_bf = _k15_float(workload.get("projected_bf"), 0.0)
    if base_rate <= 0 or projected_bf <= 0:
        neutral["status"] = "V16.3 pitcher K/BF or workload projection was unavailable."
        return neutral

    team_baseline = _k15_float(base_details.get("team_baseline_k_rate"), 0.22)
    pitch_type_matchup = base_details.get("pitch_type_matchup", {}) or {}
    player_ids = tuple(
        hitter.get("player_id") for hitter in lineup if hitter.get("player_id") not in [None, ""]
    )
    overall_profiles = fetch_mlb_lineup_profiles(player_ids, MLB_SEASON)
    split_profiles = fetch_mlb_lineup_handed_k_splits(player_ids, pitcher_hand, MLB_SEASON)
    by_order = {}
    for hitter in lineup[:9]:
        raw_order = int(_k15_float(hitter.get("order", 0), 0))
        order = raw_order // 100 if raw_order >= 100 else raw_order
        if 1 <= order <= 9 and order not in by_order:
            by_order[order] = hitter
    for hitter in lineup[:9]:
        if hitter in by_order.values():
            continue
        for order in range(1, 10):
            if order not in by_order:
                by_order[order] = hitter
                break

    profile_rows = []
    hitters_found = 0
    split_hitters = 0
    training_weights = {1: 3.0, 2: 3.0, 3: 3.0, 4: 3.0, 5: 3.0, 6: 3.0, 7: 2.0, 8: 2.0, 9: 2.0}
    for order in range(1, 10):
        hitter = by_order.get(order, {}) or {}
        pid = str(hitter.get("player_id", "") or "").replace(".0", "").strip()
        overall = overall_profiles.get(pid, {}) or {}
        split_profile = split_profiles.get(pid, {}) or {}
        overall_rate = _k15_float(overall.get("k_rate"), 0.0)
        overall_pa = _k15_float(overall.get("pa", overall.get("sample_size", 0)), 0.0)
        has_profile = bool(overall.get("available")) and overall_rate > 0 and overall_pa > 0
        if has_profile:
            hitters_found += 1
        reg = _k16_regressed_hitter_k_rate(
            overall_rate if has_profile else 0.0,
            overall_pa if has_profile else 0.0,
            split_profile,
            team_baseline,
        )
        if reg["split_available"]:
            split_hitters += 1
        arsenal_mult, arsenal_source, arsenal_score = _k16_individual_arsenal_multiplier(
            hitter.get("player", ""), pitch_type_matchup
        )
        profile_rows.append({
            "order": order, "hitter": hitter, "overall": overall,
            "overall_rate": overall_rate, "overall_pa": overall_pa,
            "has_profile": has_profile, "reg": reg,
            "arsenal_mult": arsenal_mult, "arsenal_source": arsenal_source,
            "arsenal_score": arsenal_score,
        })

    fallback_pppa = _safe_float_or_none(workload.get("opponent_pitches_per_pa"))
    pppa_numerator = 0.0
    pppa_denominator = 0.0
    for profile in profile_rows:
        pppa = _safe_float_or_none(profile["overall"].get("pitches_per_pa"))
        if pppa is None:
            pppa = fallback_pppa
        if pppa is not None:
            weight = training_weights[profile["order"]]
            pppa_numerator += weight * pppa
            pppa_denominator += weight
    lineup_pppa = pppa_numerator / pppa_denominator if pppa_denominator > 0 else None

    season_profile = dict(pitcher_profile_details.get("season_profile", {}) or {})
    recent_pitch = dict(pitcher_profile_details.get("recent_pitch_profile", {}) or {})
    discipline = dict(pitcher_profile_details.get("opponent_discipline", {}) or {})
    role_context = {
        "role_bf": _k15_float(workload.get("projected_bf"), 22.6),
        "current_role": workload.get("current_role", "Starter"),
        "prior_role": workload.get("prior_role", "Starter"),
        "hybrid_or_reliever": bool(workload.get("hybrid_or_reliever", False)),
    }
    workload = _v162_workload_from_components(
        workload.get("history", {}), season_profile, discipline,
        recent_pitch=recent_pitch, lineup_pitches_pa=lineup_pppa,
        role_context=role_context,
    )
    pitcher_profile_details["workload"] = workload
    projected_bf = _k15_float(workload.get("projected_bf"), projected_bf)
    base_rate = _v162_pitcher_rate_components(
        season_profile, workload, recent_pitch
    )["pitcher_k_rate"]

    lineup_k_rate = sum(
        training_weights[profile["order"]] * profile["reg"]["rate"] for profile in profile_rows
    ) / sum(training_weights.values())
    target_rate, regression_rate = _v162_target_k_rate(
        lineup_k_rate, pitcher_hand, pitcher_is_home,
        season_profile, workload, recent_pitch,
    )
    raw_probabilities = [
        _k16_log5_strikeout_probability(base_rate, profile["reg"]["rate"], 0.22)
        for profile in profile_rows
    ]
    shifted_probabilities = _v162_shift_probabilities(
        raw_probabilities, target_rate,
        weights=[training_weights[profile["order"]] for profile in profile_rows],
    )

    pa_expected = _k16_projected_pa_by_order(projected_bf)
    pa_six = _k16_projected_pa_by_order(25.8)
    rows = []
    expected_ks = 0.0
    six_expected_ks = 0.0
    exposure_hitter_rate = 0.0
    exposure_weight = 0.0
    batter_probabilities = []
    max_batter_expected = 0.0
    for profile, probability in zip(profile_rows, shifted_probabilities):
        order = profile["order"]
        hitter = profile["hitter"]
        reg = profile["reg"]
        projected_pa = pa_expected.get(order, 0.0)
        six_pa = pa_six.get(order, 0.0)
        hitter_expected = projected_pa * probability
        hitter_six_expected = six_pa * probability
        diagnostic_pa = max(1, min(4, int(math.floor(projected_pa + 0.5))))
        baseline_multi = _v163_baseline_multi_probability(diagnostic_pa, probability)
        tail_pmf = _v163_mean_preserving_batter_pmf(diagnostic_pa, probability)
        tail_multi = sum(mass for count, mass in tail_pmf.items() if count >= 2)
        likely_count = max(sorted(tail_pmf), key=lambda count: tail_pmf[count])
        # No 1.0 cap: this is an expected count across every projected PA.
        expected_ks += hitter_expected
        six_expected_ks += hitter_six_expected
        max_batter_expected = max(max_batter_expected, hitter_expected)
        exposure_hitter_rate += projected_pa * reg["rate"]
        exposure_weight += projected_pa
        batter_probabilities.append({
            "order": order, "player": str(hitter.get("player", "") or "Unresolved lineup slot"),
            "probability": probability, "diagnostic_pa": diagnostic_pa,
            "baseline_multi_probability": baseline_multi,
            "tail_multi_probability": tail_multi,
            "most_likely_ks": likely_count,
        })
        rows.append({
            "Order": order,
            "Player": str(hitter.get("player", "") or "Unresolved lineup slot"),
            "Bats": hitter.get("bat_side", ""),
            "Season PA": int(profile["overall_pa"]) if profile["has_profile"] else "",
            "Season K%": round(profile["overall_rate"] * 100, 1) if profile["has_profile"] else "",
            f"K% vs {'LHP' if str(pitcher_hand).upper().startswith('L') else 'RHP'}": (
                round(reg["split_rate"] * 100, 1) if reg["split_rate"] is not None else ""
            ),
            "Split PA": reg["split_pa"],
            "Regressed Hitter K%": round(reg["rate"] * 100, 1),
            "Pitches/PA": (
                round(profile["overall"].get("pitches_per_pa"), 2)
                if _safe_float_or_none(profile["overall"].get("pitches_per_pa")) is not None else ""
            ),
            "Pitch-Mix Mult": 1.0,
            "Pitch-Mix Source": profile["arsenal_source"],
            "Pitch-Mix Score": round(profile["arsenal_score"], 1) if profile["arsenal_score"] is not None else "",
            "Pitcher-vs-Hitter K%": round(probability * 100, 1),
            "Projected PA vs Starter": round(projected_pa, 2),
            "Expected Ks vs Hitter": round(hitter_expected, 2),
            "Tail Diagnostic PA": diagnostic_pa,
            "Baseline P(2+)": round(baseline_multi * 100, 1),
            "Tail P(2+)": round(tail_multi * 100, 1),
            "Most Likely Ks": likely_count,
            "Split Source": reg["source"] if profile["has_profile"] else "Team K/PA fallback for debut/missing profile",
            "Profile Available": "TRUE" if profile["has_profile"] else "FALSE",
        })

    fallback_slots = 9 - hitters_found
    coverage = hitters_found / 9.0
    neutral.update({
        "hitters": hitters_found, "split_hitters": split_hitters,
        "fallback_slots": fallback_slots, "coverage": coverage,
        "rows": pd.DataFrame(rows).sort_values("Order").reset_index(drop=True),
        "batter_probabilities": batter_probabilities,
        "regression_target_k_rate": target_rate,
        "power_prior_weight": regression_rate.get("power_prior_weight", 0.0),
        "lineup_pitches_per_pa": lineup_pppa,
        "max_batter_expected_ks": max_batter_expected,
    })
    if hitters_found < 8:
        neutral["status"] = (
            f"V16.3 requires 8 usable hitter K profiles; {hitters_found}/9 were available. "
            "The fallback projection is shown but the prop cannot publish."
        )
        return neutral

    matchup_rate = expected_ks / projected_bf
    six_rate = six_expected_ks / 25.8
    fallback_projection = _k15_float(pitcher_profile_details.get("adjusted_projection"), 0.0)
    projection_multiplier = expected_ks / fallback_projection if fallback_projection > 0 else 1.0
    return {
        "active": True,
        "projection_multiplier": projection_multiplier,
        "six_ip_projection_multiplier": (
            six_expected_ks / _k15_float(pitcher_profile_details.get("six_ip_projection"), 1.0)
            if _k15_float(pitcher_profile_details.get("six_ip_projection"), 0.0) > 0 else 1.0
        ),
        "matchup_rate": matchup_rate, "six_ip_matchup_rate": six_rate,
        "expected_ks": expected_ks, "six_ip_expected_ks": six_expected_ks,
        "hitters": hitters_found, "split_hitters": split_hitters,
        "confirmed_lineup_count": len(lineup), "fallback_slots": fallback_slots,
        "coverage": coverage,
        "exposure_hitter_rate": exposure_hitter_rate / max(1e-9, exposure_weight),
        "lineup_training_k_rate": lineup_k_rate,
        "regression_target_k_rate": target_rate,
        "regression_rate_details": regression_rate,
        "power_prior_weight": regression_rate.get("power_prior_weight", 0.0),
        "lineup_pitches_per_pa": lineup_pppa,
        "batter_probabilities": batter_probabilities,
        "max_batter_expected_ks": max_batter_expected,
        "rows": neutral["rows"],
        "status": (
            f"V16.3 true-mean + mean-preserving multi-K tail engine active: {hitters_found}/9 usable profiles and "
            f"{split_hitters}/9 handed splits. {fallback_slots} debut/missing slot(s) use the "
            f"team {team_baseline * 100:.1f}% K/PA baseline. Regression target "
            f"{target_rate * 100:.1f}% K/BF, power-prior weight "
            f"{regression_rate.get('power_prior_weight', 0.0) * 100:.0f}%, projected "
            f"{expected_ks:.2f} Ks across {projected_bf:.1f} BF. Batter expected counts "
            f"are uncapped across repeated starter matchups (max {max_batter_expected:.2f}). "
            "The replicated tail layer changes 0/1/2/3+ probabilities, never the true mean."
        ),
    }


def build_lineup_k_blend_details(game_pk, side, opponent, pitcher_hand, team_batting_rhp, team_batting_lhp, pitcher="", pitcher_arsenal_df=None, team_pitch_type_df=None, pitcher_profile_details=None):
    details = _v14_build_lineup_k_blend_details(
        game_pk, side, opponent, pitcher_hand, team_batting_rhp, team_batting_lhp,
        pitcher, pitcher_arsenal_df, team_pitch_type_df,
    )
    lineup = fetch_mlb_confirmed_lineup(game_pk, side)
    matchup = _k16_build_batter_matchup_details(
        lineup, details, pitcher_profile_details, pitcher_hand,
        pitcher_is_home=(str(side or "").lower() == "away"),
    )
    details.update({
        "confirmed_lineup_count": len(lineup),
        "lineup_slots": lineup,
        "hitters_found": int(matchup.get("hitters", 0) or 0),
        "split_hitters_found": int(matchup.get("split_hitters", 0) or 0),
        "batter_matchup_hitters": int(matchup.get("hitters", 0) or 0),
        "batter_matchup_coverage": float(matchup.get("coverage", 0.0) or 0.0),
        "batter_matchup_rows": matchup.get("rows", pd.DataFrame()),
        "individual_matchup_active": bool(matchup.get("active")),
        "fallback_hitter_slots": int(matchup.get("fallback_slots", 9) or 0),
        "status": matchup.get("status", "V16.3 matchup unavailable."),
        "source": "MLB confirmed lineup - V16.3 true mean + multi-K tail" if len(lineup) >= 8 else "MLB lineup incomplete",
    })
    if matchup.get("active"):
        expected_ks = float(matchup["expected_ks"])
        six_expected_ks = float(matchup["six_ip_expected_ks"])
        matchup_rate = float(matchup["matchup_rate"])
        details.update({
            "lineup_k_rate": matchup.get("exposure_hitter_rate"),
            "blended_k_rate": matchup.get("exposure_hitter_rate"),
            "lineup_weight": 1.0, "team_weight": 0.0,
            "k_multiplier": 1.0,
            # The batter sum directly replaces the fallback projection. These
            # multipliers stay neutral so tracking cannot imply another layer
            # was multiplied into the result.
            "projection_multiplier": 1.0,
            "six_ip_projection_multiplier": 1.0,
            "multiplier": 1.0,
            "diagnostic_multiplier": matchup.get("projection_multiplier", 1.0),
            "replacement_ratio": matchup.get("projection_multiplier", 1.0),
            "batter_matchup_k_rate": matchup_rate,
            "six_ip_batter_matchup_k_rate": float(matchup["six_ip_matchup_rate"]),
            "batter_matchup_expected_ks": expected_ks,
            "regression_target_k_rate": matchup.get("regression_target_k_rate"),
            "power_prior_weight": matchup.get("power_prior_weight", 0.0),
            "lineup_pitches_per_pa": matchup.get("lineup_pitches_per_pa"),
            "max_batter_expected_ks": matchup.get("max_batter_expected_ks", 0.0),
            "direct_projection": expected_ks,
            "direct_six_ip_projection": six_expected_ks,
        })
        if isinstance(pitcher_profile_details, dict):
            pitcher_profile_details["adjusted_projection"] = round(expected_ks, 2)
            pitcher_profile_details["six_ip_projection"] = round(six_expected_ks, 2)
            pitcher_profile_details["matchup_k_rate"] = round(matchup_rate, 5)
            pitcher_profile_details["regression_target_k_rate"] = round(
                _k15_float(matchup.get("regression_target_k_rate"), matchup_rate), 5
            )
            pitcher_profile_details["regression_rate_details"] = dict(
                matchup.get("regression_rate_details", {}) or {}
            )
            pitcher_profile_details["power_prior_weight"] = round(
                _k15_float(matchup.get("power_prior_weight"), 0.0), 4
            )
            pitcher_profile_details["individual_matchup_active"] = True
            distribution = dict(pitcher_profile_details.get("k_distribution", {}) or {})
            distribution.update({
                "k_rate": matchup_rate,
                "expected_bf": _k15_float((pitcher_profile_details.get("workload", {}) or {}).get("projected_bf"), 0.0),
                "normal_bf_mean": (pitcher_profile_details.get("workload", {}) or {}).get("normal_bf", 23.0),
                "normal_bf_sd": (pitcher_profile_details.get("workload", {}) or {}).get("normal_bf_sd", 3.2),
                "early_bf_mean": (pitcher_profile_details.get("workload", {}) or {}).get("early_bf", 14.0),
                "early_bf_sd": (pitcher_profile_details.get("workload", {}) or {}).get("early_bf_sd", 3.0),
                "early_exit_probability": (pitcher_profile_details.get("workload", {}) or {}).get("early_exit_probability", 0.09),
                "batter_probabilities": list(matchup.get("batter_probabilities", []) or []),
                "projection": expected_ks,
                "tail_model": _V163_MULTI_K_TAIL_MODEL["version"],
                "architecture": "V16.3 nine batter mean-preserving multi-K PMFs over regression BF mixture",
                "source": "V16.3 confirmed nine-slot batter probabilities with replicated P(2+) calibration",
            })
            pitcher_profile_details["k_distribution"] = distribution
            _, structural_std = _v16_pmf_moments(_v16_k_count_pmf(distribution))
            if structural_std is not None:
                pitcher_profile_details["structural_std"] = round(max(1.75, min(3.30, structural_std)), 3)
    else:
        details.update({
            "lineup_weight": 0.0, "team_weight": 1.0,
            "k_multiplier": 1.0, "projection_multiplier": 1.0,
            "six_ip_projection_multiplier": 1.0, "multiplier": 1.0,
            "diagnostic_multiplier": 1.0,
        })
    return details


def apply_lineup_k_adjustment(projection, lineup_details, use_six_ip=False):
    """Use the direct batter sum once; never multiply a prior team projection."""
    try:
        if bool((lineup_details or {}).get("individual_matchup_active")):
            key = "direct_six_ip_projection" if use_six_ip else "direct_projection"
            direct = _safe_float_or_none((lineup_details or {}).get(key))
            if direct is not None:
                return max(0.0, direct)
        return max(0.0, float(projection or 0.0))
    except Exception:
        return projection


def build_pitcher_k_context(pitcher, pitcher_team, opponent, game_environment, pitcher_this_year, pitcher_last_year, arsenal_details=None, slate_date_text=None):
    archetype = classify_pitcher_archetype(
        pitcher, pitcher_this_year, pitcher_last_year, arsenal_details
    )
    try:
        same_opponent = recent_same_opponent_start_context(
            pitcher, pitcher_team, opponent, str(slate_date_text or date.today())
        )
    except Exception:
        same_opponent = {"found": False, "status": "Same-opponent diagnostic unavailable."}
    environment = game_environment if isinstance(game_environment, dict) else build_game_environment("")
    return {
        "environment": environment, "archetype": archetype,
        "same_opponent": same_opponent, "k_projection_adjustment": 0.0,
        "early_hook_risk": environment.get("early_hook_risk", "Low"),
        "status": (
            f"V16.3 diagnostic context: {archetype.get('bucket', 'Unknown')} | "
            f"{environment.get('run_environment_tag', 'Neutral')} | numeric adjustment +0.00 K. "
            "Environment and same-opponent history are reserved for AI review."
        ),
    }


