def build_projection_data_health(lineup_details, arsenal_details, auto_weather=None, bulk_context=None):
    """Describe input completeness; this score is not a grading input."""
    lineup = lineup_details or {}
    arsenal = arsenal_details or {}
    workload = arsenal.get("workload", {}) or {}
    season = arsenal.get("season_profile", {}) or {}
    recent_pitch = arsenal.get("recent_pitch_profile", {}) or {}
    issues = []
    score = 96.0
    confirmed_count = int(lineup.get("confirmed_lineup_count", 0) or 0)
    profiles = int(lineup.get("hitters_found", 0) or 0)
    if confirmed_count < 8:
        issues.append(f"Only {confirmed_count} confirmed batting-order entries; V16 requires 8")
        score -= 24
    if profiles < 8:
        issues.append(f"Only {profiles} usable hitter K profiles; V16 requires 8")
        score -= 24
    elif profiles == 8:
        issues.append("One debut/missing hitter uses the handed team K/PA baseline")
        score -= 4
    if not bool(lineup.get("individual_matchup_active")):
        issues.append("Batter-by-batter projection inactive; team fallback is display-only")
        score -= 12
    workload_history = workload.get("history", {}) or {}
    savant_workload_games = int(recent_pitch.get("regression_sample_games", 0) or 0)
    if int(workload_history.get("sample", 0) or 0) == 0 and savant_workload_games == 0:
        issues.append("No completed pitcher workload rows; league workload prior is active")
        score -= 8
    if not bool(season.get("pitches_available")) and not workload_history.get("pitches_per_bf"):
        issues.append("Observed pitcher pitch-count rate unavailable; field remains blank")
        score -= 4
    if _safe_float_or_none(recent_pitch.get("fastball_velocity_l8")) is None:
        issues.append("Fastball velocity unavailable; locked regression uses its training mean")
        score -= 3
    if _safe_float_or_none(recent_pitch.get("release_extension_l8")) is None:
        issues.append("Release extension unavailable; locked regression uses its training mean")
        score -= 3
    if bulk_context and bulk_context.get("enabled"):
        issues.append("Bulk/opening role is projection-only and cannot publish as a V16 K play")
        score -= 12
    structural_std = _k15_float(arsenal.get("structural_std"), 2.10)
    return {
        "score": round(max(35.0, min(100.0, score)), 1),
        "issues": list(dict.fromkeys(issues)),
        "reliability_flags": [],
        "status": "V16.3 primary inputs complete" if not issues else " | ".join(list(dict.fromkeys(issues))),
        "projection_std": structural_std,
        "k_distribution": dict(arsenal.get("k_distribution", {}) or {}),
    }


@st.cache_data(ttl=300, show_spinner=False)
def get_global_k_calibration():
    history = _history_before_today()
    # The recent-form tab can briefly return an empty frame even when the sheet
    # still contains rows (for example, during a transient API/read failure).
    # Use the model's intended V16 identity fallback rather than blocking the
    # entire builder while trying to sort a missing helper column.
    if history is None or history.empty or "_date" not in history.columns:
        return {
            "intercept": 0.0, "slope": 1.0, "sample": 0,
            "source": "V16 identity calibration while recent-form history is unavailable",
            "error_std": 2.10,
        }
    history = history.sort_values("_date", ascending=False)
    if "Role" in history.columns:
        history = history[history["Role"].astype(str).str.upper().eq("STARTER")].copy()
    history = history.head(300)
    if len(history) < 120:
        return {
            "intercept": 0.0, "slope": 1.0, "sample": int(len(history)),
            "source": "V16 identity calibration until 120 completed V16 starter projections",
            "error_std": 2.10,
        }
    x = history["_raw"].astype(float).tolist()
    y = history["_actual"].astype(float).tolist()
    mean_x = sum(x) / len(x)
    mean_y = sum(y) / len(y)
    variance = sum((value - mean_x) ** 2 for value in x)
    slope = (
        sum((raw - mean_x) * (actual - mean_y) for raw, actual in zip(x, y)) / variance
        if variance > 1e-9 else 1.0
    )
    intercept = mean_y - slope * mean_x
    slope = max(0.85, min(1.10, slope))
    intercept = max(-0.50, min(0.50, intercept))
    errors = [actual - (intercept + slope * raw) for raw, actual in zip(x, y)]
    error_std = statistics.pstdev(errors) if len(errors) >= 2 else 2.10
    return {
        "intercept": round(intercept, 4), "slope": round(slope, 4),
        "sample": len(history), "source": "Rolling V16-only last 300 completed projections",
        "error_std": round(max(1.75, min(3.20, error_std)), 3),
    }


def pitcher_projection_reliability(pitcher, volatility, lineup_details, calibration, recent_form, role="Starter", bulk_confidence="", data_health=None):
    health = data_health if isinstance(data_health, dict) else {}
    score = _k15_float(health.get("score"), 85.0)
    reasons = list(health.get("issues", []) or [])
    role_upper = str(role or "Starter").upper()
    if role_upper != "STARTER":
        score -= 15
        reasons.append(f"{role_upper.title()} role is not publication eligible")
    if str(volatility or "").upper().startswith("HIGH"):
        score -= 6
        reasons.append("high historical K volatility")
    elif str(volatility or "").upper().startswith("MEDIUM"):
        score -= 3
        reasons.append("medium historical K volatility")
    return {
        "score": round(max(35.0, min(95.0, score)), 1),
        "reasons": list(dict.fromkeys(reasons)),
        "grading_use": "Descriptive only; V16 market grade does not use reliability points.",
    }


def calibrate_pitcher_projection(raw_projection, pitcher, opponent, volatility, lineup_details, recent_form=None, role="Starter", bulk_confidence="", archetype="", data_health=None):
    raw = max(0.0, float(raw_projection or 0.0))
    global_fit = get_global_k_calibration()
    global_projection = max(0.0, float(global_fit["intercept"]) + float(global_fit["slope"]) * raw)
    distribution = dict((data_health or {}).get("k_distribution", {}) or {})
    old_expected_bf = _v16_distribution_expected_bf(distribution) if distribution else 0.0
    old_rate = _safe_float_or_none(distribution.get("k_rate")) if distribution else None
    if distribution and str(role or "Starter").upper() != "STARTER" and old_rate and raw > 0 and old_expected_bf > 0:
        target_bf = raw / old_rate
        scale = max(0.20, min(1.20, target_bf / old_expected_bf))
        distribution["normal_bf_mean"] = max(3.0, _k15_float(distribution.get("normal_bf_mean"), 23.0) * scale)
        distribution["early_bf_mean"] = max(2.0, _k15_float(distribution.get("early_bf_mean"), 14.0) * scale)
    expected_bf = _v16_distribution_expected_bf(distribution) if distribution else 0.0
    if distribution and expected_bf > 0:
        distribution["k_rate"] = max(0.01, min(0.60, global_projection / expected_bf))
        distribution["expected_bf"] = expected_bf
        distribution["projection"] = global_projection
    pmf = _v16_k_count_pmf(distribution)
    _, pmf_std = _v16_pmf_moments(pmf)
    expected_std = max(2.05, min(3.30, pmf_std if pmf_std is not None else _k15_float(global_fit.get("error_std"), 2.10)))
    reliability = pitcher_projection_reliability(
        pitcher, volatility, lineup_details, global_fit, recent_form or {}, role=role,
        bulk_confidence=bulk_confidence, data_health=data_health or {},
    )
    no_adjustment = {"adjustment": 0.0, "sample": 0, "status": "V16 residual point adjustments disabled"}
    return {
        "raw_projection": round(raw, 3),
        "global_projection": round(global_projection, 3),
        "pitcher_adjustment": 0.0, "opponent_adjustment": 0.0,
        "final_projection": round(global_projection, 3),
        "shadow_projection": round(global_projection, 3),
        "expected_std": round(expected_std, 3),
        "reliability": reliability,
        "global_fit": global_fit,
        "pitcher_history": no_adjustment,
        "opponent_history": no_adjustment,
        "archetype_shadow": {"adjustment": 0.0, "status": "AI diagnostic only"},
        "data_health": data_health or {},
        "distribution": distribution,
        "status": (
            f"V16.3 true-mean regression projection {raw:.2f} → global calibration {global_projection:.2f}; "
            "the multi-K layer reshapes the count PMF but preserves that mean. Pitcher, opponent, "
            f"archetype and recent-result point adjustments remain disabled. Mixture SD {expected_std:.2f}."
        ),
    }


def k_market_probabilities(projection, line, expected_std, distribution_details=None):
    try:
        projection = float(projection)
        line = float(line)
        expected_std = max(0.75, float(expected_std))
    except Exception:
        return {"over": 0.5, "under": 0.5, "push": 0.0}
    distribution = dict(distribution_details or {})
    if distribution:
        expected_bf = _v16_distribution_expected_bf(distribution)
        if expected_bf > 0:
            distribution["k_rate"] = max(0.01, min(0.60, projection / expected_bf))
        distribution["projection"] = projection
        distribution["target_mean"] = projection
        pmf = _v16_k_count_pmf(distribution)
        if pmf:
            if abs(line - round(line)) < 1e-9:
                integer_line = int(round(line))
                under = sum(probability for value, probability in pmf.items() if value < integer_line)
                push = pmf.get(integer_line, 0.0)
                over = sum(probability for value, probability in pmf.items() if value > integer_line)
            else:
                under = sum(probability for value, probability in pmf.items() if value < line)
                push = 0.0
                over = sum(probability for value, probability in pmf.items() if value > line)
            over = max(0.005, over)
            under = max(0.005, under)
            total = over + under + push
            summary = _v163_pmf_summary(pmf)
            mean, std = summary["mean"], summary["std"]
            return {
                "over": over / total, "under": under / total, "push": push / total,
                "distribution": (
                    "V16.3 mean-preserving multi-K batter PMFs over regression BF mixture"
                    if distribution.get("batter_probabilities")
                    else "V16.3 beta-binomial fallback over regression BF mixture"
                ),
                "mean": round(mean, 3) if mean is not None else projection,
                "std": round(std, 3) if std is not None else expected_std,
                "mode": summary.get("mode"), "median": summary.get("median"),
                "true_projection": round(projection, 3),
                "mean_preservation_error": (
                    round(float(mean) - projection, 10) if mean is not None else None
                ),
                "tail_model_active": bool(distribution.get("batter_probabilities")),
                "tail_model_version": _V163_MULTI_K_TAIL_MODEL["version"],
            }
    integer_line = abs(line - round(line)) < 1e-9
    if integer_line:
        lower = (line - 0.5 - projection) / expected_std
        upper = (line + 0.5 - projection) / expected_std
        under = _normal_cdf(lower)
        push = max(0.0, _normal_cdf(upper) - _normal_cdf(lower))
        over = max(0.0, 1.0 - under - push)
    else:
        over = 1.0 - _normal_cdf((line - projection) / expected_std)
        under = 1.0 - over
        push = 0.0
    return {
        "over": _cap(over, 0.01, 0.99), "under": _cap(under, 0.01, 0.99),
        "push": _cap(push, 0.0, 0.50), "distribution": "Normal fallback",
        "mean": round(projection, 3), "std": round(expected_std, 3),
        "mode": int(round(projection)), "median": int(round(projection)),
        "true_projection": round(projection, 3), "mean_preservation_error": None,
        "tail_model_active": False, "tail_model_version": "normal_fallback",
    }


def select_k_market_side(probabilities, over_odds=-110, under_odds=None, require_quoted=False):
    """Select the better-priced PMF side; the continuous mean is audit-only."""
    probabilities = probabilities or {}
    raw_over = parse_american_odds(over_odds)
    under_input = under_odds if under_odds is not None else (None if require_quoted else over_odds)
    raw_under = parse_american_odds(under_input)
    over_available = raw_over is not None
    under_available = raw_under is not None
    parsed_over = raw_over
    parsed_under = raw_under
    parsed_over = parsed_over if parsed_over is not None else -110
    parsed_under = parsed_under if parsed_under is not None else -110
    push = max(0.0, min(1.0, float(probabilities.get("push", 0.0) or 0.0)))
    over_probability = max(0.0, min(1.0, float(probabilities.get("over", 0.5) or 0.0)))
    under_probability = max(0.0, min(1.0, float(probabilities.get("under", 0.5) or 0.0)))
    over_edge = over_probability - american_odds_to_implied_prob(parsed_over) * (1.0 - push)
    under_edge = under_probability - american_odds_to_implied_prob(parsed_under) * (1.0 - push)
    if require_quoted and not over_available:
        over_edge = -1e9
    if require_quoted and not under_available:
        under_edge = -1e9
    choose_over = (over_edge, over_probability) >= (under_edge, under_probability)
    return {
        "side": "OVER" if choose_over else "UNDER",
        "probability": over_probability if choose_over else under_probability,
        "odds": parsed_over if choose_over else parsed_under,
        "price_edge": over_edge if choose_over else under_edge,
        "over_probability": over_probability, "under_probability": under_probability,
        "over_odds": parsed_over, "under_odds": parsed_under,
        "over_price_edge": over_edge, "under_price_edge": under_edge,
        "push_probability": push,
        "over_available": over_available, "under_available": under_available,
        "available": over_available if choose_over else under_available,
    }


def strikeout_bet_grade(exp_k, six_k, ipg_this, ipg_last, line, volatility, odds=-110, reliability=None, expected_std=None, distribution_details=None, under_odds=None):
    try:
        exp_k = float(exp_k)
        line = float(line)
        expected_std = float(expected_std if expected_std is not None else 2.10)
    except Exception:
        return "PASS", 0.0
    signed_edge = exp_k - line
    probabilities = k_market_probabilities(
        exp_k, line, expected_std, distribution_details=distribution_details
    )
    selection = select_k_market_side(probabilities, odds, under_odds)
    side = selection["side"]
    probability = selection["probability"]
    price_edge = selection["price_edge"]
    grade = "PASS"
    if side == "OVER":
        if probability >= 0.68 and price_edge >= 0.06:
            grade = "STRONG OVER"
        elif probability >= 0.63 and price_edge >= 0.04:
            grade = "OVER"
        elif probability >= 0.60 and price_edge >= 0.025:
            grade = "LEAN OVER"
    else:
        if probability >= 0.69 and price_edge >= 0.06:
            grade = "STRONG UNDER"
        elif probability >= 0.64 and price_edge >= 0.04:
            grade = "UNDER"
        elif probability >= 0.60 and price_edge >= 0.025:
            grade = "LEAN UNDER"
    return grade, round(signed_edge, 3)


def strikeout_under_first_loss_cushion(projection, line):
    """Distance from the mean projection to the first K total that loses an Under."""
    try:
        projection = float(projection)
        line = float(line)
    except Exception:
        return None
    if projection >= line:
        return None
    # Under 4.5 first loses at 5; Under 5.0 pushes at 5 and first loses at 6.
    return round((math.floor(line) + 1) - projection, 3)


def pitcher_k_strength_score(exp_k, six_k, line, volatility, ipg_this, ipg_last, reliability=None, selected_probability=None, price_edge=None):
    try:
        probability = float(selected_probability if selected_probability is not None else 0.50)
        advantage = float(price_edge if price_edge is not None else 0.0)
    except Exception:
        return 0.0
    score = 38.0
    score += max(0.0, min(40.0, (probability - 0.50) * 200.0))
    score += max(-10.0, min(22.0, advantage * 160.0))
    return round(max(0.0, min(100.0, score)), 1)


def _v15_5_apply_k_publication_rules(grade, role="Starter", lineup_details=None, arsenal_details=None, volatility="", game_environment=None):
    """V16 live publication: traditional starters and 8 usable profiles only."""
    original = str(grade or "PASS").upper().strip()
    published = original
    reasons = []
    role_upper = str(role or "Starter").upper().strip()
    lineup = lineup_details or {}
    arsenal = arsenal_details or {}
    confirmed_count = int(lineup.get("confirmed_lineup_count", 0) or 0)
    profiles = int(lineup.get("hitters_found", 0) or 0)
    active = bool(lineup.get("individual_matchup_active"))
    source_confirmed = "confirmed" in str(lineup.get("source", "")).lower()
    eight_hitter_passed = confirmed_count >= 8 and profiles >= 8 and active and source_confirmed
    fallback_slots = int(lineup.get("fallback_hitter_slots", max(0, 9 - profiles)) or 0)

    workload = arsenal.get("workload", {}) or {}
    normal_pitches = _k15_float(workload.get("normal_pitches"), 0.0)
    normal_bf = _k15_float(workload.get("normal_bf"), 0.0)
    hybrid_or_reliever = bool(workload.get("hybrid_or_reliever", False))
    workload_supported = normal_pitches >= 85.0 and normal_bf >= 21.5
    partial_workload_support = normal_pitches >= 85.0 or normal_bf >= 21.5
    early_exit_risk = str(workload.get("early_exit_risk", "Medium") or "Medium").title()

    if original != "PASS" and role_upper != "STARTER":
        published = "PASS"
        reasons.append(f"V16 publishes traditional starter props only; {role_upper.title()} retained as projection-only")
    if published != "PASS" and hybrid_or_reliever:
        published = "PASS"
        reasons.append("V16 publishes established traditional starters only; hybrid/reliever workload is projection-only")
    if published != "PASS" and not eight_hitter_passed:
        published = "PASS"
        reasons.append(
            f"V16 requires a confirmed order and 8 usable hitter K profiles; "
            f"found {confirmed_count} order entries and {profiles} profiles"
        )
    if published in ["LEAN OVER", "OVER", "STRONG OVER"]:
        if not partial_workload_support:
            published = "PASS"
            reasons.append(
                f"Starter workload lacks support: normal regime {normal_pitches:.1f} pitches / {normal_bf:.1f} BF"
            )
        elif not workload_supported and published in ["OVER", "STRONG OVER"]:
            published = "LEAN OVER"
            reasons.append(
                f"Partial workload support ({normal_pitches:.1f} pitches / {normal_bf:.1f} BF); capped at Lean Over"
            )
        if early_exit_risk == "High" and published in ["STRONG OVER", "OVER"]:
            published = "LEAN OVER"
            reasons.append("High modeled early-exit risk caps Over at Lean Over")
        elif published == "STRONG OVER" and early_exit_risk == "Medium":
            published = "OVER"
            reasons.append(f"{early_exit_risk} modeled early-exit risk prevents Strong Over")
    if published != "PASS" and eight_hitter_passed:
        reasons.append(
            f"V16 8-profile rule passed ({profiles}/9); {fallback_slots} debut/missing slot(s) use team K/PA"
        )
    support = "FULL" if workload_supported else "PARTIAL" if partial_workload_support else "NO"
    meta = {
        "published_grade": published,
        "shadow_grade": published,
        "grade_restriction_reason": " | ".join(reasons),
        "workload_support": support if role_upper == "STARTER" else "ROLE-INELIGIBLE",
        # Legacy tracking key/column name retained so old sheet schemas keep working.
        "nine_hitter_passed": _v15_5_bool_text(eight_hitter_passed),
        "lineup_profile_coverage": (
            f"{profiles}/9 usable profiles; V16 requires 8; {fallback_slots} team-baseline fallback slot(s)"
        ),
        "under_shadow_only": "FALSE",
        "early_exit_risk": early_exit_risk,
    }
    return published, " | ".join(reasons), meta


def ensure_model_version_logged():
    """Log the unchanged full model and the independently versioned V16 K engine."""
    try:
        frame = read_sheet(MODEL_CHANGE_LOG_TAB, MODEL_CHANGE_LOG_COLUMNS)
        if frame is None:
            frame = pd.DataFrame(columns=MODEL_CHANGE_LOG_COLUMNS)
        existing = set(frame["Version"].astype(str).tolist()) if not frame.empty else set()
        rows = []
        if MODEL_VERSION not in existing:
            rows.append({
                "Version": MODEL_VERSION, "Effective Date": today_et_string(),
                "Changes": "V15.8.1 non-pitcher model components retained without modification.",
                "Created Time ET": _recent_form_time_label(),
            })
        if K_MODEL_VERSION not in existing:
            rows.append({
                "Version": K_MODEL_VERSION, "Effective Date": today_et_string(),
                "Changes": (
                    "V16.3 pitcher strikeouts: V16.2 locked true-mean K-rate/BF regressions retained; "
                    "nine confirmed batter probabilities with uncapped repeated-PA expected counts; "
                    "replicated mean-preserving P(2+) calibration and convolved 0/1/2/3+ batter PMFs "
                    "over normal/early-exit BF; probability/price-edge side selection; true mean, mode, "
                    "median and both tail probabilities tracked; unreplicated archetype boosts excluded."
                ),
                "Created Time ET": _recent_form_time_label(),
            })
        if rows:
            frame = pd.concat([frame, pd.DataFrame(rows)], ignore_index=True)
            write_sheet(MODEL_CHANGE_LOG_TAB, frame, MODEL_CHANGE_LOG_COLUMNS)
    except Exception:
        pass


